import time
import gpiozero
import sys
import signal
import socket
import adafruit_busio.SPI as SPI
import MCP3008
import paho.mqtt.client as mqtt

class MCP3008ADC:
    def __init__(self, spi, cs_pin):
        self.spi = spi
        self.cs_pin = gpiozero.DigitalOutputDevice(cs_pin, active_high=False)
        self.adc = MCP3008.MCP3008(spi, cs_pin)

    def read(self):
        self.cs_pin.off()
        readings = [self.adc.read() for _ in range(5)]
        self.cs_pin.on()
        return sum(readings) / len(readings)

def check_sensor_presence(mcp):
    try:
        mcp.read()
        return True
    except OSError:
        return False

def check_bus_error(mcp):
    try:
        mcp.read()
        return False
    except RuntimeError:
        return True

def setup_motors():
    motor_a_forward_pin = gpiozero.DigitalOutputDevice(27, initial_value=False)
    motor_a_backward_pin = gpiozero.DigitalOutputDevice(22, initial_value=False)
    motor_b_clockwise_pin = gpiozero.DigitalOutputDevice(24, initial_value=False)
    motor_b_counterclockwise_pin = gpiozero.DigitalOutputDevice(25, initial_value=False)

    motor_a_enable_pin = gpiozero.PWMOutputDevice(17, 1000)
    motor_b_enable_pin = gpiozero.PWMOutputDevice(23, 1000)

    return motor_a_forward_pin, motor_a_backward_pin, motor_b_clockwise_pin, motor_b_counterclockwise_pin, motor_a_enable_pin, motor_b_enable_pin

def main():
    try:
        spi = busio.SPI(clock=11, MOSI=10, MISO=9, sck=8)
        spi2 = busio.SPI(clock=11, MOSI=10, MISO=9, sck=7)

        adc1 = MCP3008ADC(spi, 8)
        adc2 = MCP3008ADC(spi2, 7)

        if not check_sensor_presence(adc1) or not check_sensor_presence(adc2):
            print("Error: Sensors not connected.")
            sys.exit(1)

        if check_bus_error(adc1) or check_bus_error(adc2):
            print("Error: Bus error detected.")
            sys.exit(1)

        motor_pins, motor_enable_pins = setup_motors()

        socket_server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        socket_server.bind(('0.0.0.0', 12345))
        socket_server.listen()

        print("Listening for commands on port 12345...")

        mqtt_client = mqtt.Client()
        mqtt_client.on_connect = lambda client, userdata, flags, rc: print(f"Connected with result code {rc}")

        while True:
            try:
                client_socket, addr = socket_server.accept()
                print(f"Connected by {addr}")

                while True:
                    command = client_socket.recv(1024).decode().strip()

                    if not command:
                        break

                    if command == "WATER_PLANT_1":
                        water_plant_1(adc1, motor_pins, motor_enable_pins)
                    elif command == "WATER_PLANT_2":
                        water_plant_2(adc2, motor_pins, motor_enable_pins)
                    elif command == "GET_SENSOR_DATA":
                        sensor_data = get_sensor_data(adc1, adc2)
                        client_socket.sendall(str(sensor_data).encode())
                    elif command.startswith("SET_THRESHOLD"):
                        threshold = int(command.split(" ")[1])
                        set_threshold(threshold, adc1, adc2)
                    elif command.startswith("SET_WATERING_DURATION"):
                        duration = int(command.split(" ")[1])
                        set_watering_duration(duration)
                    else:
                        client_socket.sendall("Invalid command.".encode())

                client_socket.close()

            except ConnectionResetError:
                print("Client disconnected.")
                continue
            except Exception as e:
                print(f"Error: {e}")
                break

        socket_server.close()

    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

    finally:
        motor_a_forward_pin.off()
        motor_a_backward_pin.off()
        motor_b_clockwise_pin.off()
        motor_b_counterclockwise_pin.off()
        motor_a_enable_pin.off()
        motor_b_enable_pin.off()

def water_plant(adc, motor_pins, motor_enable_pins, duration=10):
    for _ in range(duration):
        motor_pins.on()
        motor_enable_pins.on()
        time.sleep(1)
        motor_pins.off()
        motor_enable_pins.off()
        time.sleep(1)

    moisture = adc.read()
    print(f"Moisture level: {moisture}")

def water_plant_1(adc1, motor_pins, motor_enable_pins):
    if moisture_level_ok(adc1):
        water_plant(adc1, motor_pins, motor_enable_pins)

def water_plant_2(adc2, motor_pins, motor_enable_pins):
    if moisture_level_ok(adc2):
        water_plant(adc2, motor_pins, motor_enable_pins)

def moisture_level_ok(adc):
    moisture = adc.read()
    return moisture > THRESHOLD

def get_sensor_data(adc1, adc2):
    moisture1 = adc1.read()
    moisture2 = adc2.read()
    return (moisture1, moisture2)

def set_threshold(threshold, adc1, adc2):
    global THRESHOLD
    THRESHOLD = threshold
    print(f"Threshold set to {THRESHOLD}")

def set_watering_duration(duration):
    global WATERING_DURATION
    WATERING_DURATION = duration
    print(f"Watering duration set to {WATERING_DURATION} seconds")

if __name__ == "__main__":
    THRESHOLD = 500
    WATERING_DURATION = 10
    try:
        main()
    except KeyboardInterrupt:
        print("Exiting...")

