import time
import spidev
import struct
import gpiozero
import adafruit_mcp3008
import paho.mqtt.client as mqtt

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 50000
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def send_spi_command(self, data):
        try:
            return self.spi.xfer2(data)
        except (OSError, IOError):
            print("Error during SPI transmission. Check device and bus.")
            self.close()
            raise

    def extract_10bit(self, response):
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        data = self.send_spi_command([0x01, 0x80, 0x00])
        if len(data) != 3:
            print("Invalid response from SPI device.")
            self.close()
            raise Exception("Invalid response length")
        return self.extract_10bit(data)

    def convert_to_weight(self, raw_data):
        return float(raw_data) * (5.0 / 1023.0)

    def close(self):
        try:
            self.spi.close()
        except OSError:
            pass

    def main(self):
        try:
            load_cell = LoadCellReader()
            while True:
                raw_data = load_cell.read_raw_data()
                weight = load_cell.convert_to_weight(raw_data)
                print(f'Weight: {weight:.2f} kg')
                time.sleep(0.5)
        except KeyboardInterrupt:
            load_cell.close()
            print("Shutting down...")
        except Exception as e:
            load_cell.close()
            print(f"Fatal error: {e}")
            raise

if __name__ == "__main__":
    load_cell = LoadCellReader()
    load_cell.main()

