import logging
import time
import smbus2
import Adafruit_ADS1x15
import adafruit_ads1x15.analog_in
import adafruit_ads1x15.analog_in_multiplexer as multiplexer
import paho.mqtt.client as mqtt

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.debug = debug
        self.bus = smbus2.SMBus(busnum)
        self.i2c_address = address
        self.ads = Adafruit_ADS1x15.ADS1015(self.i2c_address)
        self.channel = adafruit_ads1x15.analog_in.AnalogIn(self.ads, mux_channel=0)
        self.pga = 6144
        self.sps = 250
        self.last_conversion_result = None
        self.comparator_active = False
        self.comparator_threshold_high = 2047
        self.comparator_threshold_low = 0
        self.comparator_active_low = True
        self.comparator_traditional_mode = True
        self.comparator_latching = False
        self.comparator_num_readings = 1

        if self.debug:
            logging.basicConfig(level=logging.DEBUG)

        try:
            self.ads.configure_single_ended(self.pga, self.sps)
            config = self.ads.read_register(0x00)
            if config != 0x06:
                raise Exception(f"ADS1015 not found at address 0x{self.i2c_address:02X}")
        except Exception as e:
            if self.debug:
                logging.error(e)
            raise

    def read_adc_single_ended(self, channel=0, pga=None, sps=None):
        if pga is None:
            pga = self.pga
        if sps is None:
            sps = self.sps

        try:
            self.channel = self.ads.analog_in[channel]
            self.ads.configure_single_ended(pga, sps)
            result = self.channel.value
            if self.debug:
                logging.debug(f"Read ADC: channel={channel}, result={result}")
            return result
        except Exception as e:
            if self.debug:
                logging.error(e)
            raise

    def start_continuous_conversion(self, channel=0, pga=None, sps=None):
        if pga is None:
            pga = self.pga
        if sps is None:
            sps = self.sps

        try:
            self.channel = self.ads.analog_in[channel]
            self.ads.configure_single_ended(pga, sps)
            self.channel.start_conversion()
            if self.debug:
                logging.debug(f"Started continuous conversion: channel={channel}")
        except Exception as e:
            if self.debug:
                logging.error(e)
            raise

    def get_last_conversion_results(self):
        try:
            result = self.channel.result
            if self.debug:
                logging.debug(f"Last conversion result: {result}")
            return result
        except Exception as e:
            if self.debug:
                logging.error(e)
            raise

    def start_single_ended_comparator(self, channel=0, threshold_high=None, threshold_low=None, pga=None, sps=None, active_low=None, traditional_mode=None, latching=None, num_readings=None):
        if pga is None:
            pga = self.pga
        if sps is None:
            sps = self.sps
        if active_low is None:
            active_low = self.comparator_active_low
        if traditional_mode is None:
            traditional_mode = self.comparator_traditional_mode
        if latching is None:
            latching = self.comparator_latching
        if num_readings is None:
            num_readings = self.comparator_num_readings

        try:
            self.channel = self.ads.analog_in[channel]
            self.comparator_active = True
            self.comparator_threshold_high = threshold_high
            self.comparator_threshold_low = threshold_low
            self.comparator_pga = pga
            self.comparator_sps = sps
            self.comparator_active_low = active_low
            self.comparator_traditional_mode = traditional_mode
            self.comparator_latching = latching
            self.comparator_num_readings = num_readings

            self.channel.start_comparator(self.comparator_threshold_high, self.comparator_threshold_low, self.comparator_pga, self.comparator_sps, self.comparator_active_low, self.comparator_traditional_mode, self.comparator_latching, self.comparator_num_readings)
            if self.debug:
                logging.debug(f"Started single-ended comparator: channel={channel}, threshold_high={self.comparator_threshold_high}, threshold_low={self.comparator_threshold_low}, pga={self.comparator_pga}, sps={self.comparator_sps}, active_low={self.comparator_active_low}, traditional_mode={self.comparator_traditional_mode}, latching={self.comparator_latching}, num_readings={self.comparator_num_readings}")
        except Exception as e:
            if self.debug:
                logging.error(e)
            raise

    def stop_single_ended_comparator(self):
        try:
            self.channel.stop_comparator()
            self.comparator_active = False
            if self.debug:
                logging.debug("Stopped single-ended comparator")
        except Exception as e:
            if self.debug:
                logging.error(e)
            raise

    def __del__(self):
        self.stop_single_ended_comparator()
        self.bus.close()

