            self.comparator_active_low = active_low
            self.comparator_traditional_mode = traditional_mode
            self.comparator_latching = latching
            self.comparator_num_readings = num_readings

            self.channel.start_comparator(self.comparator_threshold_high, self.comparator_threshold_low, self.comparator_pga, self.comparator_sps, self.comparator_active_low, self.comparator_traditional_mode, self.comparator_latching, self.comparator_num_readings)
            if self.debug:
                logging.debug(f"Started single-ended comparator: channel={channel}, threshold_high={self.comparator_threshold_high}, threshold_low={self.comparator_threshold_low}, pga={self.comparator_pga}, sps={self.comparator_sps}, active_low={self.comparator_active_low}, traditional_mode={self.comparator_traditional_mode}, latching={self.comparator_latching}, num_readings={self.comparator_num_readings}")
        except Exception as e:
            if self.debug:
                logging.error(e)
            raise

    def stop_single_ended_comparator(self):
        try:
            self.channel.stop_comparator()
            self.comparator_active = False
            if self.debug:
                logging.debug("Stopped single-ended comparator")
        except Exception as e:
            if self.debug:
                logging.error(e)
            raise

