# Set up logging
logging.basicConfig(filename='greenhouse.log', level=logging.INFO, format='%(asctime)s - %(message)s')

# DHT22 sensor configuration
dht_device = adafruit_dht.DHT22(4)

# Relay pins
pump = gpiozero.Relay(17)
fan = gpiozero.Relay(27)
light = gpiozero.Relay(22)
led = gpiozero.LED(25)

# ADC channel 0 on MCP3008
spi = spidev.SpiDev()
spi.open(0, 0)

def control_pump(command):
    if command == 'on':
        pump.on()
    elif command == 'off':
        pump.off()

def control_fan(command):
    if command == 'on':
        fan.on()
    elif command == 'off':
        fan.off()

def control_light(command):
    if command == 'on':
        light.on()
    elif command == 'off':
        light.off()

def set_led_status(status):
    if status == 'online':
        led.on()
    elif status == 'offline':
        led.off()
    elif status == 'error':
        for _ in range(5):
            led.on()
            time.sleep(0.2)
            led.off()
            time.sleep(0.2)
    elif status == 'synchronizing':
        for _ in range(5):
            led.on()
            time.sleep(0.2)
            led.off()
            time.sleep(0.2)

def read_adc(channel):
    spi.max_speed_hz = 100000
    read = spi.xfer2([1, (8 + channel << 4) | 0x03, 0])
    data = ((read[1] & 3) << 8) + read[2]
    return data

def read_sensors():
    try:
        dht_device.try_again_forever(
            lambda: dht_device.measure_temperature()
        )
        temp_c = dht_device.temperature
        humidity = dht_device.humidity
        logging.info(f'Temperature: {temp_c:.1f}°C, Humidity: {humidity:.1f}%')
        return temp_c, humidity
    except RuntimeError as e:
        logging.warning(f'DHT22 sensor read error: {e}')
        return None, None

def watchdog():
    last_action = time.time()
    while True:
        if time.time() - last_action > 600:
            logging.warning('No sensor data or actuator command processed for 600 seconds, restarting...')
            os.execv(sys.executable, sys.argv)
        last_action = time.time()
        time.sleep(1)

def setup_gpio():
    try:
        pump.on_off = control_pump
        fan.on_off = control_fan
        light.on_off = control_light
        led.on_off = set_led_status
        return True
    except gpiozero.GpioDeviceNotFoundError as e:
        logging.error(f'GPIO device not found: {e}')
        return False

def setup_spi():
    try:
        spi.open(0, 0)
        spi.max_speed_hz = 100000
        return True
    except OSError as e:
        logging.error(f'SPI bus error: {e}')
        return False

def main():
    if not setup_gpio():
        logging.error('Failed to set up GPIO pins, exiting...')
        return

    if not setup_spi():
        logging.error('Failed to set up MCP3008 ADC, exiting...')
        return

    signal.signal(signal.SIGTERM, lambda *args: cleanup_and_exit())
    signal.signal(signal.SIGINT, lambda *args: cleanup_and_exit())

    watchdog_thread = threading.Thread(target=watchdog)
    watchdog_thread.start()

    while True:
        temp_c, humidity = read_sensors()
        if temp_c is not None and humidity is not None:
            read_adc_value = read_adc(0)
            logging.info(f'ADC value: {read_adc_value}')
        time.sleep(300)

def cleanup_and_exit():
    pump.off()
    fan.off()
    light.off()
    led.off()
    spi.close()
    sys.exit(0)

if __name__ == '__main__':
    main()

