class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.log_queue = log_queue

        if self.sensor_type == "digital":
            self.sensor = DigitalInputDevice(gpio_pins[0])
        elif self.sensor_type == "analog":
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = spi_speed

            self.channel = channels[0]
            self.adc = gpiozero.ADC(self.channel)

        self.last_event_time = 0

    def read(self):
        if self.sensor_type == "digital":
            return self.sensor.value
        elif self.sensor_type == "analog":
            data = self.spi.xfer2([1, (8 << 4) | (self.channel << 1), 0, 0])
            adc_value = ((data[2] & 31) << 8) + data[3]
            return adc_value
        else:
            raise ValueError("Invalid sensor type")

    def detect_event(self):
        if self.sensor_type == "digital":
            if self.sensor.value == 1:
                return True
        elif self.sensor_type == "analog":
            adc_value = self.read()
            if adc_value >= self.threshold:
                return True
        return False

    def debounce(self):
        current_time = time.monotonic()
        if current_time - self.last_event_time < 0.1:
            return False
        self.last_event_time = current_time
        return True

    def run(self):
        while True:
            if self.detect_event() and self.debounce():
                if self.log_queue:
                    self.log_queue.put((self.sensor_id, time.monotonic()))
            time.sleep(1 / self.sample_rate)

    def stop(self):
        if self.sensor_type == "digital":
            self.sensor.deinit()
        if self.sensor_type == "analog":
            self.spi.close()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--sensor_type", choices=["digital", "analog"], required=True)
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=float, default=10)
    parser.add_argument("--log_file", default=None)
    parser.add_argument("--gpio_pins", nargs="+", type=int, required=True if "--sensor_type" == "digital" else None)
    parser.add_argument("--channels", nargs="+", type=int, required=True if "--sensor_type" == "analog" else None)
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", nargs="+", type=int, required=True)

    args = parser.parse_args()

    log_queue = queue.Queue()
    if args.log_file:
        logging.basicConfig(filename=args.log_file, level=logging.INFO)
    else:
        logging.basicConfig(level=logging.INFO)

    sensors = []
    for sensor_id, sensor_type, threshold, gpio_pins, channels in zip(args.sensor_ids, args.sensor_type, args.threshold, args.gpio_pins, args.channels):
        try:
            if sensor_type == "digital":
                GPIO.setmode(GPIO.BCM)
                GPIO.setup(gpio_pins[0], GPIO.IN)
            elif sensor_type == "analog":
                spi = spidev.SpiDev()
                spi.open(0, 0)
                spi.max_speed_hz = args.spi_speed

            sensor = SoundSensor(sensor_id, sensor_type, threshold, args.sample_rate, gpio_pins, channels, args.spi_speed, log_queue)
            sensors.append(sensor)
        except Exception as e:
            logging.error(f"Error initializing sensor {sensor_id}: {e}")

    mqtt_client = MQTT_Client("sound_sensor", host="mqtt.example.com", port=1883)
    mqtt_client.on_connect = lambda client, userdata, flags, rc: mqtt_client.subscribe("sound_events/#")
    mqtt_client.connect()

    try:
        for sensor in sensors:
            sensor_thread = threading.Thread(target=sensor.run)
            sensor_thread.start()

        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()

    mqtt_client.disconnect()

    if sensors:
        for sensor in sensors:
            if sensor.sensor_type == "digital":
                GPIO.cleanup(sensor.sensor.pin)

if __name__ == "__main__":
    main()

