handler.setFormatter(logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s'))
logger.addHandler(handler)
logger.setLevel(logging.WARNING)

def read_config():
    config = configparser.ConfigParser()
    config.read('config.txt')

    sensors = []
    for section in config.sections():
        try:
            sensor_type = config[section]['Sensor' + section[-1]]
            sensor_address = int(config[section]['Sensor' + section[-1] + '_Address'], 16)
            sensor_id = int(config[section]['Sensor' + section[-1] + '_ID'])
            sampling_interval = int(config[section]['Sampling_Interval_Seconds'])

            if sensor_type in ['bmp280', 'bme280', 'ms8607']:
                sensors.append((sensor_type, sensor_address, sensor_id, sampling_interval))
        except Exception as e:
            logger.error(f"Error reading config for section {section}: {e}")

    return sensors, sampling_interval

def init_sensors(sensors):
    i2c = busio.I2C(board.SCL, board.SDA)
    devices = []

    for sensor_type, sensor_address, sensor_id, _ in sensors:
        try:
            if sensor_type == 'bmp280':
                device = adafruit_bmp280.Adafruit_BMP280(i2c, sensor_address)
                if device.read_id() != 0x58:
                    logger.warning(f"Invalid BMP280 chip ID at address 0x{sensor_address:02X}")
                    continue
            elif sensor_type == 'bme280':
                device = adafruit_bme280.Adafruit_BME280_I2C(i2c, sensor_address)
                if device.read_id() != 0x60:
                    logger.warning(f"Invalid BME280 chip ID at address 0x{sensor_address:02X}")
                    continue
            elif sensor_type == 'ms8607':
                device = adafruit_ms5611.MS5611(i2c, sensor_address)

            devices.append((sensor_type, device))
        except Exception as e:
            logger.error(f"Error initializing sensor of type {sensor_type} at address 0x{sensor_address:02X}: {e}")

    return devices

def read_and_store_data(devices, sampling_interval):
    db = sqlite3.connect('wildlife_data.db')
    cursor = db.cursor()

    cursor.execute('''CREATE TABLE IF NOT EXISTS sensor_data (
                        timestamp TEXT PRIMARY KEY,
                        sensor_type TEXT,
                        sensor_id INTEGER,
                        pressure_pa INTEGER,
                        temperature_c REAL,
                        humidity_percent REAL
                    )''')

    while True:
        for sensor_type, device in devices:
            try:
                if sensor_type == 'bmp280':
                    pressure_pa = device.pressure
                    temperature_c = device.temperature
                elif sensor_type == 'bme280':
                    pressure_pa = device.pressure
                    temperature_c = device.temperature
                    humidity_percent = device.humidity
                elif sensor_type == 'ms8607':
                    pressure_pa = device.pressure * 100
                    temperature_c = device.temperature

                if pressure_pa < 70000 or pressure_pa > 110000:
                    logger.warning(f"Invalid pressure reading {pressure_pa} Pa from {sensor_type} sensor")
                    continue
                if temperature_c < -20 or temperature_c > 50:
                    logger.warning(f"Invalid temperature reading {temperature_c}°C from {sensor_type} sensor")
                    continue
                if sensor_type in ['bme280', 'ms8607'] and humidity_percent < 0 or humidity_percent > 100:
                    logger.warning(f"Invalid humidity reading {humidity_percent}% from {sensor_type} sensor")
                    humidity_percent = None

                timestamp = datetime.now().isoformat()
                cursor.execute("INSERT INTO sensor_data VALUES (?, ?, ?, ?, ?, ?)", (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent))
                db.commit()
            except Exception as e:
                logger.error(f"Error reading data from {sensor_type} sensor: {e}")

        time.sleep(sampling_interval)

def mqtt_publish(devices, sampling_interval):
    mqtt_broker = "your_mqtt_broker"
    mqtt_port = 1883
    mqtt_topic = "wildlife_data"
    client = mqtt.Client()
    client.on_connect = on_connect
    client.connect(mqtt_broker, mqtt_port, 60)
    client.loop_start()

    while True:
        for sensor_type, device in devices:
            try:
                if sensor_type == 'bmp280':
                    pressure_pa = device.pressure
                    temperature_c = device.temperature
                elif sensor_type == 'bme280':
                    pressure_pa = device.pressure
                    temperature_c = device.temperature
                    humidity_percent = device.humidity
                elif sensor_type == 'ms8607':
                    pressure_pa = device.pressure * 100
                    temperature_c = device.temperature

                message = f"{sensor_type}: pressure={pressure_pa} Pa, temperature={temperature_c}°C, humidity={humidity_percent}%"
                client.publish(mqtt_topic, message)
            except Exception as e:
                logger.error(f"Error publishing data from {sensor_type} sensor: {e}")

        time.sleep(sampling_interval)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        logger.info("Connected to MQTT broker")
    else:
        logger.error(f"Failed to connect to MQTT broker: {rc}")

if __name__ == "__main__":
    try:
        sensors, sampling_interval = read_config()
        devices = init_sensors(sensors)

        if not devices:
            logger.info("No valid sensors found in config.txt, exiting...")
            sys.exit(0)

        if len(devices) == 1:
            read_and_store_data(devices, sampling_interval)
        elif len(devices) == 2:
            read_and_store_data(devices[0], sampling_interval)
            mqtt_publish(devices[1], sampling_interval)
        else:
            read_and_store_data(devices[0], sampling_interval)
            mqtt_publish(devices[1:], sampling_interval)

    except KeyboardInterrupt:
        logger.info("Received SIGINT, exiting...")
        sys.exit(0)
    except Exception as e:
        logger.error(f"Unhandled error: {e}")
        traceback.print_exc()
        sys.exit(1)

import os
