from picamera2 import Picamera2
from io import BytesIO
from PIL import Image
from gpiozero import MotionSensor
from adafruit_blinkt import blinkt
from flask import Flask, render_template, Response, request, send_file
from flask_paho_mqtt import MQTTClient
from config import Config
from mail_config import MailConfig

class Camera:
    def __init__(self):
        self.camera = Picamera2.create(context=None)
        self.config = Config()
        self.motion_sensor = MotionSensor(self.config.motion_sensor_pin)
        self.frame_boundary = "frame"
        self.last_email_sent = 0
        self.last_frame_time = 0
        self.last_motion_time = 0
        self.mqtt_client = MQTTClient(client_id="object_detector", broker=self.config.mqtt_broker, port=self.config.mqtt_port)

    def start_camera(self):
        try:
            self.camera.configure(self.get_camera_config())
            self.camera.start()
            self.capture_thread = self.camera.create_capture_pipeline()
            self.capture_thread.start()
            self.last_frame_time = time.monotonic()
            self.last_motion_time = time.monotonic()
            self.motion_sensor.when_motion = self.on_motion
            self.mqtt_client.connect()
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            sys.exit(1)

    def get_camera_config(self):
        stream_config = self.camera.create_video_configuration(main={"format": "YUV420", "size": (640, 480), "framerate": 30})
        stream_config.set_transform(Picamera2.Tf.VFLIP)
        return stream_config

    def get_frame(self):
        try:
            frame = next(self.capture_thread)
            buffer = BytesIO()
            frame.save(buffer, format="JPEG")
            buffer.seek(0)
            return buffer.getvalue()
        except Exception as e:
            logging.error(f"Error capturing frame: {e}")
            return None

    def get_object(self, classifier):
        frame = self.get_frame()
        if frame is None:
            return (None, False)

        try:
            result = classifier.predict(Image.open(BytesIO(frame)))
            if len(result) > 0:
                return (frame, True)
            else:
                return (frame, False)
        except Exception as e:
            logging.error(f"Error performing object detection: {e}")
            return (frame, False)

    def get_object_with_basic_motion_detection(self):
        current_time = time.monotonic()
        elapsed_time = current_time - self.last_motion_time
        if elapsed_time > self.config.motion_detection_interval:
            self.last_motion_time = current_time
            self.on_motion()

        frame, detected = self.get_object(Config.classifier_motion_detector)
        if frame is None:
            return (None, False)

        if detected:
            self.last_motion_time = current_time

        return (frame, detected)

    def on_motion(self):
        if not self.config.mqtt_enabled:
            return

        try:
            frame = self.get_frame()
            if frame is None:
                return

            msg = MQTTClient.publish(self.mqtt_client, topic="motion_detected", payload=base64.b64encode(frame), qos=1)
            if msg[0] == 0:
                logging.info("Motion detected and MQTT message sent")
            else:
                logging.warning("Failed to send MQTT message for motion detection")
        except Exception as e:
            logging.error(f"Error sending MQTT message for motion detection: {e}")

    def stop_camera(self):
        self.camera.stop_preview()
        self.camera.close()
        self.mqtt_client.disconnect()

    def send_email(self, frame, config):
        if not config.send_email_notifications:
            return

        current_time = time.monotonic()
        elapsed_time = current_time - self.last_email_sent
        if elapsed_time < config.email_send_interval:
            return

        self.last_email_sent = current_time

        try:
            MailConfig.send_email(frame, config)
        except Exception as e:
            logging.error(f"Error sending email: {e}")

app = Flask(__name__)
camera = Camera()

@app.route("/")
def index():
    return render_template("index.html", config=Config())

@app.route("/video_feed")
def video_feed():
    return Response(
        generate_video_feed(),
        mimetype="multipart/x-mixed-replace; boundary=frame"
    )

def generate_video_feed():
    while True:
        frame, detected = camera.get_object_with_basic_motion_detection()
        if frame is None:
            continue

        yield (f"--{camera.frame_boundary}\r\n"
               f"Content-Type: image/jpeg\r\n\r\n"
               f"{base64.b64encode(frame).decode('utf-8')}\r\n\r\n")

        if detected and camera.config.send_email_notifications:
            camera.send_email(frame, camera.config)

def on_exit(*args):
    camera.stop_camera()
    GPIO.cleanup()

def on_signal(signal, frame):
    on_exit()
    sys.exit(0)

if __name__ == "__main__":
    atexit.register(on_exit)
    signal.signal(signal.SIGINT, on_signal)
    signal.signal(signal.SIGTERM, on_signal)
    if not camera.start_camera():
        sys.exit(1)
    app.run(host="0.0.0.0", port=Config.web_port)

