import os
import time
import cv2
import pyzbar.pyzbar as pyzbar
import configparser
import logging
import threading
import queue
import sys
import signal
import picamera2
import adafruit_blinka

# Set up logging
logging.basicConfig(filename='inventory.log', level=logging.INFO,
                    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Read configuration
config = configparser.ConfigParser()
config.read('config.ini')

motion_threshold = int(config['DEFAULT']['motion_threshold'])
redundancy_time_window = float(config['DEFAULT']['redundancy_time_window'])
frame_buffer_size = int(config['DEFAULT']['frame_buffer_size'])
cloud_upload_interval = int(config['DEFAULT'].get('cloud_upload_interval', 60))
reinit_delay = float(config['DEFAULT']['reinit_delay'])
watchdog_timeout = 30

# Initialize cameras and frame buffers
cameras = {}
frame_queues = {}

def camera_thread(camera_id):
    global cameras, frame_queues

    try:
        camera = picamera2.PiCamera2()
        camera.start_preview()
        camera.crop_region = (0, 0, camera.resolution[0], camera.resolution[1])
        camera.capture_sequence([picamera2.ToNV21Array(use_camera_memory=True)], use_camera_memory=True)
        cameras[camera_id] = camera
        frame_queues[camera_id] = queue.Queue(frame_buffer_size)

        while True:
            try:
                frame = camera.capture_array(format='bgr24')
                frame_queues[camera_id].put(frame)
            except Exception as e:
                logger.error(f'Error reading camera {camera_id}: {e}')
                del cameras[camera_id]
                break

            time.sleep(0.1)

    except Exception as e:
        logger.error(f'Error initializing camera {camera_id}: {e}')
        del cameras[camera_id]

def process_frames():
    global cameras, frame_queues, redundancy_time_window

    last_qr_codes = {}

    while True:
        for camera_id, frame_queue in frame_queues.items():
            try:
                if cameras[camera_id] is None:
                    continue

                frame = frame_queue.get(timeout=1)
                if frame is None:
                    continue

                gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                diff_frame = cv2.absdiff(gray_frame, last_qr_codes.get(camera_id, gray_frame))
                _, thresholded_frame = cv2.threshold(diff_frame, motion_threshold, 255, cv2.THRESH_BINARY)

                qr_codes = pyzbar.decode(thresholded_frame)

                for qr_code in qr_codes:
                    data = qr_code.data.decode('utf-8')
                    timestamp = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())
                    camera_id_str = f'camera_{camera_id}'

                    if data not in last_qr_codes or time.time() - last_qr_codes[data] > redundancy_time_window:
                        logger.info(f'{timestamp} - {camera_id_str} - {data}')
                        with open('inventory.log', 'a') as log_file:
                            log_file.write(f'{timestamp} - {camera_id_str} - {data}\n')
                        last_qr_codes[data] = time.time()

            except Exception as e:
                logger.error(f'Error processing frame from camera {camera_id}: {e}')

        time.sleep(0.1)

def watchdog():
    last_qr_code_time = 0

    while True:
        if all([camera is not None for camera in cameras.values()]):
            last_qr_code_time = time.time()
        else:
            break

        time.sleep(1)

        if time.time() - last_qr_code_time > watchdog_timeout:
            logger.warning('No QR code detected for 30 seconds, restarting...')
            os.execv(sys.executable, [sys.executable] + sys.argv)

def cloud_upload():
    global last_qr_codes

    with open('inventory.log', 'r') as log_file:
        lines = log_file.readlines()

    for line in lines:
        print(line, end='')

    if os.path.exists('inventory.log'):
        os.remove('inventory.log')

    last_qr_codes = {}

def main():
    threading.Thread(target=camera_thread, args=(0,)).start()
    threading.Thread(target=camera_thread, args=(2,)).start()
    threading.Thread(target=process_frames).start()
    threading.Thread(target=watchdog).start()

    try:
        while True:
            time.sleep(cloud_upload_interval)
            cloud_upload()
    except KeyboardInterrupt:
        for camera in cameras.values():
            camera.close()
        for frame_queue in frame_queues.values():
            frame_queue.queue.clear()

if __name__ == '__main__':
    main()

import os
import sys
import time
import cv2
import numpy as np
import picamera2 as picamera
import gpiozero
import paho.mqtt.client as mqtt
from pathlib import Path
from time import strftime
from adafruit_blinkt import Blinkt

# Motion detection threshold, duration, and max size (in bytes)
THRESHOLD = 5
DURATION = 5
MAX_SIZE = 1073741824  # 1 GB

def create_directory(directory):
    try:
        directory.mkdir(parents=True, exist_ok=True)
    except FileNotFoundError:
        print(f"Error creating directory: {directory}")
        sys.exit(1)
    except PermissionError:
        print("Error creating directory: Permission denied")
        sys.exit(1)

def get_oldest_file(directory):
    files = [f for f in directory.glob("*.h264")]
    if not files:
        return None
    return min(files, key=lambda f: os.path.getmtime(f))

def delete_oldest_files(directory, max_size):
    total_size = sum([os.path.getsize(f) for f in directory.glob("*.h264")])
    if total_size > max_size:
        files_to_delete = []
        to_delete_size = total_size - max_size
        for f in sorted(directory.glob("*.h264"), key=lambda f: os.path.getmtime(f), reverse=True):
            size = os.path.getsize(f)
            if to_delete_size > size:
                files_to_delete.append(f)
                to_delete_size -= size
            else:
                break
        for f in files_to_delete:
            os.remove(f)

def motion_detected(frame1, frame2):
    return np.abs(np.mean(frame1) - np.mean(frame2)) > THRESHOLD

def record_video(camera, duration):
    recording_file = Path("/home/pi/security_footage", f"{strftime('%Y-%m-%d_%H-%M-%S')}.h264")
    try:
        camera.start_recording(recording_file, format="H264", max_duration=duration)
        print(f"Recording video to {recording_file}")
    except picamera.exc.PiCameraValueError as e:
        print(f"Error starting video recording: {e}")
        sys.exit(1)

def stop_recording(camera):
    try:
        camera.stop_recording()
        print("Stopped recording")
    except picamera.exc.PiCameraValueError as e:
        print(f"Error stopping video recording: {e}")
        sys.exit(1)

def main():
    create_directory(Path("/home/pi/security_footage"))
    delete_oldest_files(Path("/home/pi/security_footage"), MAX_SIZE)

    camera = picamera.PiCamera2()
    try:
        camera.configure(picamera2.Config(
            main={
                "format": "YUV420",
                "size": (320, 240),
                "framerate": 15
            }
        ))
        camera.start_preview()

        motion_detected_prev = None
        blinkt = Blinkt()
        while True:
            try:
                frame = camera.capture_array()
                frame = cv2.cvtColor(frame, cv2.COLOR_YUV420p2RGB)
                frame = np.mean(frame, axis=2)

                if motion_detected_prev is not None:
                    if motion_detected(frame, motion_detected_prev):
                        motion_detected_prev = frame
                        blinkt.all(255)
                        record_video(camera, DURATION)
                        time.sleep(2)
                        stop_recording(camera)

                motion_detected_prev = frame
                time.sleep(2)
            except KeyboardInterrupt:
                print("Exiting...")
                break
            except picamera.exc.PiCameraValueError as e:
                print(f"Error capturing frame: {e}")
                break
            except cv2.error as e:
                print(f"Error converting frame to grayscale: {e}")
                break

        camera.stop_preview()
        camera.close()

if __name__ == "__main__":
    args = sys.argv[1:]
    for arg in args:
        if arg == "--threshold":
            THRESHOLD = int(sys.argv[args.index(arg) + 1])
        elif arg == "--duration":
