# Motion detection threshold, duration, and max size (in bytes)
THRESHOLD = 5
DURATION = 5
MAX_SIZE = 1073741824  # 1 GB

def create_directory(directory):
    try:
        directory.mkdir(parents=True, exist_ok=True)
    except FileNotFoundError:
        print(f"Error creating directory: {directory}")
        sys.exit(1)
    except PermissionError:
        print("Error creating directory: Permission denied")
        sys.exit(1)

def get_oldest_file(directory):
    files = [f for f in directory.glob("*.h264")]
    if not files:
        return None
    return min(files, key=lambda f: os.path.getmtime(f))

def delete_oldest_files(directory, max_size):
    total_size = sum([os.path.getsize(f) for f in directory.glob("*.h264")])
    if total_size > max_size:
        files_to_delete = []
        to_delete_size = total_size - max_size
        for f in sorted(directory.glob("*.h264"), key=lambda f: os.path.getmtime(f), reverse=True):
            size = os.path.getsize(f)
            if to_delete_size > size:
                files_to_delete.append(f)
                to_delete_size -= size
            else:
                break
        for f in files_to_delete:
            os.remove(f)

def motion_detected(frame1, frame2):
    return np.abs(np.mean(frame1) - np.mean(frame2)) > THRESHOLD

def record_video(camera, duration):
    recording_file = Path("/home/pi/security_footage", f"{strftime('%Y-%m-%d_%H-%M-%S')}.h264")
    try:
        camera.start_recording(recording_file, format="H264", max_duration=duration)
        print(f"Recording video to {recording_file}")
    except picamera.exc.PiCameraValueError as e:
        print(f"Error starting video recording: {e}")
        sys.exit(1)

def stop_recording(camera):
    try:
        camera.stop_recording()
        print("Stopped recording")
    except picamera.exc.PiCameraValueError as e:
        print(f"Error stopping video recording: {e}")
        sys.exit(1)

def main():
    create_directory(Path("/home/pi/security_footage"))
    delete_oldest_files(Path("/home/pi/security_footage"), MAX_SIZE)

