import os
import time
import json
import logging
import smbus2
import numpy as np
import adafruit_amg8833 as amg8833
import adafruit_amg88xx
import picamera2
import matplotlib.pyplot as plt
from matplotlib.colors import Jet
from matplotlib.ticker import MaxNLocator
from gpiozero import LED
import signal
from PIL import Image
from PIL.iO import UnsupportedImageModeError
import paho.mqtt.client as mqtt

class BeehiveMonitor:
    def __init__(self, config_path):
        self.config = self.load_config(config_path)
        self.i2c = smbus2.SMBus(1)
        self.sensor = None
        self.camera = None
        self.frame_buffer = np.zeros((300, 8, 8), dtype=np.uint16)
        self.frame_index = 0
        self.motion_detected = False
        self.led = LED(2)
        self.log_file = None
        self.log_handler = None
        self.mqtt_client = mqtt.Client()

    def load_config(self, config_path):
        try:
            with open(config_path, 'r') as f:
                config = json.load(f)
        except FileNotFoundError:
            config = {
                'sampling_rate': 5,
                'motion_detection_threshold': 1.0,
                'logging_file_path': 'beehive.log',
                'log_max_size': 1048576,
                'enable_camera': False
            }
        return config

    def init_sensor(self):
        for _ in range(3):
            try:
                self.sensor = amg8833.AMG8833(self.i2c, address=0x69)
                break
            except RuntimeError:
                time.sleep(2)
        if not self.sensor:
            logging.error("Failed to initialize thermal sensor")
            raise Exception("Sensor initialization failed")

    def init_camera(self):
        try:
            camera_config = picamera2.Config(
                main={
                    'format': 'YUV422',
                    'size': (800, 600),
                    'framerate': 15
                }
            )
            self.camera = picamera2.Camera(camera_config)
            self.camera.start()
            return True
        except Exception as e:
            logging.warning(f"Failed to initialize camera: {e}")
            return False

    def sample_and_detect_motion(self):
        try:
            data = self.sensor.pixel_array
            if self.frame_index == 0:
                self.frame_buffer[:] = data
            else:
                diff = np.abs(data - self.frame_buffer[self.frame_index - 1])
                mean_diff = np.mean(diff)
                if mean_diff > self.config['motion_detection_threshold'] and self.config['enable_camera']:
                    self.motion_detected = True
                    self.capture_image()
                self.frame_buffer[self.frame_index] = data
                self.frame_index = (self.frame_index + 1) % len(self.frame_buffer)
        except Exception as e:
            logging.error(f"Error during sensor read: {e}")

    def capture_image(self):
        try:
            self.camera.capture('temp.jpg', format='jpeg')
            img = Image.open('temp.jpg')
            if img.mode != 'RGB':
                raise UnsupportedImageModeError(img.mode)
            img = img.resize((800, 600))
            self.led.on()
        except Exception as e:
            logging.warning(f"Error during image capture: {e}")

    def plot_heatmap(self):
        try:
            img = self.sensor.image
            img = np.rot90(img, k=3)
            img = (img - img.min()) / (img.max() - img.min())
            img = img * 255
            img = img.astype(np.uint8)
            plt.imshow(img, cmap='jet', interpolation='nearest')
            plt.colorbar()
            plt.title(f"{time.strftime('%Y-%m-%d %H:%M:%S')}")
            plt.pause(0.01)
        except Exception as e:
            logging.error(f"Error during heatmap plot: {e}")

    def log_event(self, event):
        try:
            if not self.log_file:
                self.log_file = open(self.config['logging_file_path'], 'w')
                self.log_handler = logging.RotatingFileHandler(self.log_file, maxBytes=self.config['log_max_size'], backupCount=5)
                formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
                self.log_handler.setFormatter(formatter)
                logging.getLogger().addHandler(self.log_handler)
            logging.getLogger().log(level=logging.INFO, msg=event)
        except Exception as e:
            logging.error(f"Error during log event: {e}")

    def run(self):
        try:
            self.i2c.open()
            self.init_sensor()
            self.init_camera()

            try:
                while True:
                    self.sample_and_detect_motion()
                    if self.motion_detected:
                        self.log_event(f"Motion detected")
                        self.motion_detected = False
                    if self.config['enable_camera']:
                        self.plot_heatmap()
                    time.sleep(1 / self.config['sampling_rate'])

                    if self.config['enable_camera']:
                        self.camera.capture_sequence([('temp.jpg', 'jpeg'))
                        self.plot_heatmap()

                    time.sleep(5)
            except KeyboardInterrupt:
                self.log_event("Received SIGINT, shutting down")
            except Exception as e:
                self.log_event(f"Unexpected error: {e}")

        except Exception as e:
            self.log_event(f"Error during initialization: {e}")
            self.i2c.close()
            raise e
        finally:
            self.i2c.close()
            if self.log_file:
                self.log_file.close()
            if self.camera:
                self.camera.close()

if __name__ == "__main__":
    config_path = 'config.json'
    beehive_monitor = BeehiveMonitor(config_path)
    beehive_monitor.run()

