import time
import RPi.GPIO as GPIO
import smbus
import gpiozero
import adafruit_ssd1306
import paho.mqtt.client as mqtt
import psutil
from time import sleep

# LED pins
LED_PINS = [17, 18, 23, 27, 22]

# I2C LCD
I2C_BUS = 1
I2C_ADDR = 0x27

# MQTT broker and topic
MQTT_BROKER = "your_mqtt_broker"
MQTT_TOPIC = "led_control"

def setup_i2c_lcd():
    bus = smbus.SMBus(I2C_BUS)
    i2c_address = 0x3C | (I2C_ADDR << 1)
    lcd = adafruit_ssd1306.SSD1306_I2C(i2c_address, bus)
    return lcd

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PINS, GPIO.OUT)

def light_led(cls):
    try:
        for i, pin in enumerate(LED_PINS):
            if cls == i:
                GPIO.output(pin, GPIO.HIGH)
            else:
                GPIO.output(pin, GPIO.LOW)
            sleep(1)
            GPIO.output(pin, GPIO.LOW)
    except GPIO.IOError as e:
        print(f"Error during LED control: {e}")
    finally:
        GPIO.cleanup()

def get_cpu_usage():
    try:
        cpu_percent = psutil.cpu_percent()
        temp = psutil.sensors_temperatures()['cpu-thermal'][0].current
        return cpu_percent, temp
    except (psutil.NoSuchProcess, psutil.NoSuchDisk, psutil.NoSuchSensor) as e:
        print(f"Error during CPU usage/temperature read: {e}")
        return None, None

def display_cpu_info(lcd):
    try:
        cpu_usage, temp = get_cpu_usage()
        if cpu_usage is not None:
            lcd.fill(0)
            lcd.text("CPU Usage:", 0, 0)
            lcd.text(f"{cpu_usage:.1f}%", 0, 10)
            lcd.text("Temp:", 54, 0)
            lcd.text(f"{temp}°C", 54, 10)
    except Exception as e:
        print(f"Error during LCD display: {e}")

def mqtt_on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker")
        client.subscribe(MQTT_TOPIC)

def mqtt_on_message(client, userdata, msg):
    try:
        cls = int(msg.payload.decode())
        if 0 <= cls <= 4:
            light_led(cls)
    except ValueError:
        print("Invalid class index received")

def main():
    lcd = setup_i2c_lcd()
    setup_gpio()

    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = mqtt_on_connect
    mqtt_client.on_message = mqtt_on_message
    mqtt_client.connect(MQTT_BROKER)

    try:
        while True:
            try:
                cpu_usage, temp = get_cpu_usage()
                if cpu_usage is not None:
                    display_cpu_info(lcd)
            except Exception as e:
                print(f"Error during main loop: {e}")
            sleep(1)
    except KeyboardInterrupt:
        lcd.fill(0)
        lcd.display.off()
        GPIO.cleanup()
        mqtt_client.disconnect()

if __name__ == "__main__":
    main()

