            self.display = SSD1306(i2c_address=self.i2c_address, rst=None)
        elif self.display_type == "SSIOLED":
            self.display = SSIOLED(i2c_address=self.i2c_address)
        else:
            raise ValueError("Invalid display type. Supported types are SSD1306 and SSIOLED.")

        self.display.clear()
        self.display.show()

    def _get_gif_files(self):
        gif_files = []
        for entry in os.scandir(self.gif_folder):
            if entry.is_file() and entry.name.lower().endswith(".gif"):
                gif_files.append(entry.name)
        return gif_files

    def _load_image(self, gif_file):
        with Image.open(os.path.join(self.gif_folder, gif_file)) as img:
            try:
                img_load = ImageLoad(img)
                gif = GifImageFile(img_load.get_raw())
                return gif
            except Exception as e:
                print(f"Error loading GIF file '{gif_file}': {e}")
                return None

    def _draw_frame(self, frame):
        width, height = frame.size
        if width != self.display.width or height != self.display.height:
            pad_frame = ImageOps.expand(frame, border=(0, 0, (self.display.width - width) // 2, (self.display.height - height) // 2, fill=(0, 0, 0)))
        else:
            pad_frame = frame

        canvas = self.display.canvas
        canvas.clear()
        canvas.blit(pad_frame, (0, 0))
        canvas.show()

    def _play_gif(self, gif):
        for frame in gif.get_data():
            if frame[0] == b'-':
                self.frame_duration = frame[1:]
                self.frame_duration = int(self.frame_duration.hex(), 16)
            elif frame[0] == b'!':
                self.frame_duration = 100
            else:
                self._draw_frame(Image.frombytes(
                    "RGB", frame[1], frame[2:]))
                time.sleep(self.frame_duration / 1000.0)

    def play(self):
        gif_files = self._get_gif_files()
        if not gif_files:
            print("No GIF files found in the specified folder.")
            return

        for gif_file in gif_files:
            gif = self._load_image(gif_file)
            if gif is None:
                continue
            self.current_gif = gif
            self.current_frame = 0
            self._play_gif(self.current_gif)

    def run(self):
        self._init_display()
        try:
            self.play()
            while True:
                self.current_frame += 1
                if self.current_frame >= len(self.current_gif):
                    self.current_frame = 0
                    if self.current_gif != self._get_gif_files()[0]:
                        self.current_gif = self._load_image(self._get_gif_files()[0])
                        if self.current_gif is None:
                            continue
                    self.current_frame = 0
                    time.sleep(1)
                self._play_gif(self.current_gif)
        except KeyboardInterrupt:
            print("Exiting...")
        except Exception as e:
            print(f"Error during GIF playback: {e}")
        finally:
            self.display.clear()
            self.display.show()
            self.display.deinit()

if __name__ == "__main__":
    gif_player = GifPlayer()
    gif_player.run()

