from adafruit_gpio.util import i2c as adafruit_i2c

I2C_BUS = 1  # Use the default I2C bus (physical pins 3 for SDA and 5 for SCL)
I2C_ADDR = 0x20  # Use the default PCF8574 expander address (0x20)

def read_pcf8574(i2c):
    try:
        output_register = 0x00
        i2c.write_byte_data(I2C_ADDR, output_register, 0xFF)  # Set all pins as inputs with internal pull-up
        input_register = i2c.read_byte_data(I2C_ADDR, output_register)
        return input_register
    except (IOError, OSError) as e:
        print(f"I2C bus error: {e}")
        time.sleep(1)
        return -1

def main():
    with adafruit_i2c.get_i2c_bus(I2C_BUS) as i2c:
        while True:
            sensor_data = read_pcf8574(i2c)
            if sensor_data == -1:
                continue

            for i in range(8):
                if (sensor_data & (1 << i)) == 0:  # Check if the sensor is LOW (obstacle detected)
                    print(f'Obstacle detected by sensor {i}')

            time.sleep(0.1)  # Polling interval of 100 milliseconds

    i2c.close()  # Release the I2C bus on Ctrl-C or any other exit path

if __name__ == "__main__":
