# Default configuration
DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"system_code": "10101", "unit_codes": [1, 2, 3]}
    ]
}

def setup_logging(log_file):
    logger = logging.getLogger(__name__)
    logger.setLevel(logging.INFO)

    formatter = logging.Formatter(
        "%(asctime)s [%(levelname)s] %(message)s"
    )

    file_handler = logging.handlers.RotatingFileHandler(
        log_file, maxBytes=1048576, backupCount=5
    )
    file_handler.setFormatter(formatter)
    logger.addHandler(file_handler)

    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)
    logger.addHandler(console_handler)

def read_config(config_file="greenhouse_config.json"):
    try:
        with open(config_file) as f:
            config = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        config = DEFAULT_CONFIG
        logging.warning(f"Using default configuration: {e}")

    return config

def transmit_code(transmitter_pin, system_code, unit_code, state):
    transmitter = Device(transmitter_pin, output_type="data")

    sync_pulse = [(1, 2000), (1, 2000)]
    data_pulse = {
        1: [(0, 300), (1, 1000), (0, 300)],
        0: [(1, 1000), (0, 300), (1, 1000)],
    }
    code = [sync_pulse] + [
        data_pulse[bit] + [(1, 0)] for bit in bin(int(state))[2:][::-1]
    ] + [sync_pulse]

    for i, bits in enumerate(code):
        for bit in bits:
            transmitter.on()
            time.sleep(bit[0])
            transmitter.off()
            time.sleep(bit[1])
        time.sleep(0.1)

    for outlet in OUTLET_CONFIGS:
        if outlet["system_code"] == system_code and unit_code in outlet["unit_codes"]:
            time.sleep(0.5)
            transmit_code(transmitter_pin, system_code, "1", "0")  # Debounce

def setup_transmitter(transmitter_pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(transmitter_pin, GPIO.OUT)

def teardown_transmitter():
    GPIO.cleanup()

def setup_dht22():
    i2c = board.I2C()
    dht = adafruit_dht.DHT22(i2c)
    dht.trigger_temp = True
    return dht

def teardown_dht22(dht):
    if dht:
        dht.exit()

def read_temperature(dht):
    try:
        temp_celsius = dht.temperature
        humidity = dht.humidity
    except RuntimeError as e:
        logging.error(f"DHT22 error: {e}")
        return None, None
    except OSError as e:
        logging.error(f"I2C bus error: {e}")
        return None, None

    return temp_celsius, humidity

def transmit_and_log(transmitter_pin, dht):
    temp_celsius, humidity = read_temperature(dht)

    if temp_celsius is None or humidity is None:
        return

    logging.info(f"Temperature: {temp_celsius:.1f}°C, Humidity: {humidity:.1f}%")

    for outlet in OUTLET_CONFIGS:
        state = "on" if temp_celsius > outlet["temperature_threshold"] else "off"
        transmit_code(transmitter_pin, outlet["system_code"], outlet["unit_codes"][0], state)

async def sensor_reading_task(transmitter_pin, dht):
    while True:
        await asyncio.sleep(READ_INTERVAL)
        transmit_and_log(transmitter_pin, dht)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        logging.info("Connected to MQTT broker")
        client.subscribe("#")

def on_message(client, userdata, msg):
    command, outlet_name = msg.topic.split("/")[2:]

    if command == "on":
        transmit_code(transmitter_pin, OUTLET_CONFIGS[0]["system_code"], OUTLET_CONFIGS[0]["unit_codes"][outlet_name - 1], "1")
    elif command == "off":
        transmit_code(transmitter_pin, OUTLET_CONFIGS[0]["system_code"], OUTLET_CONFIGS[0]["unit_codes"][outlet_name - 1], "0")
    elif command == "status":
        status = "off" if OUTLET_CONFIGS[0]["unit_codes"][outlet_name - 1] not in STATE else "on"
        client.publish(f"greenhouse/status/{outlet_name}", status)

def setup_mqtt(broker, port):
    client = mqtt_client.Client()
    client.on_connect = on_connect
    client.on_message = on_message

    if not client.connect(broker, port):
        logging.error("Failed to connect to MQTT broker")
        sys.exit(1)

def teardown_mqtt(client):
    client.disconnect()

def main():
    config = read_config()

    transmitter_pin = config["gpio_transmitter_pin"]
    dht22_pin = config["gpio_dht22_pin"]
    read_interval = config["dht22_read_interval"]
    log_file = config["log_file"]

    setup_logging(log_file)
    logging.info("Starting greenhouse controller")

    transmitter = Device(transmitter_pin, output_type="data")
    dht = setup_dht22()

    try:
        setup_transmitter(transmitter_pin)
        mqtt_broker = "your_mqtt_broker"
        mqtt_port = 1883
        setup_mqtt(mqtt_broker, mqtt_port)

        asyncio.run(sensor_reading_task(transmitter_pin, dht))

        while True:
            try:
                command = input("Enter command (on/off/status outlet_name): ").lower().split()

                if len(command) == 3:
                    outlet_name = int(command[2])
                    if outlet_name <= len(OUTLET_CONFIGS[0]["unit_codes"]):
                        transmit_code(transmitter_pin, OUTLET_CONFIGS[0]["system_code"], OUTLET_CONFIGS[0]["unit_codes"][outlet_name - 1], command[1])
                    else:
                        logging.error(f"Invalid outlet number: {outlet_name}")
                else:
                    logging.error("Invalid command format")
            except KeyboardInterrupt:
                break

    finally:
        teardown_dht22(dht)
        teardown_transmitter()
        teardown_mqtt(client)

if __name__ == "__main__":
    main()

import time
import sys
