import smbus2
import crc8
from adafruit_bus_device.i2c_device import I2CDevice

logger = logging.getLogger(__name__)

class DHT20:
    def __init__(self):
        self.bus = None
        self.address = 0x38
        self.crctab = crc8.CRCTable(0x31)

        try:
            self.bus = smbus2.SMBus(1)
            device = I2CDevice(self.bus, self.address)
            self.bus.write_i2c_block_data(self.address, 0x71, [0x03, 0x00])  # Soft reset
            time.sleep(1)

            status = self.bus.read_i2c_block_data(self.address, 0x71)
            if status[0] != 0x44:
                logger.error("DHT20 not found")
                self.bus = None
                return

        except (IOError, OSError) as e:
            logger.error(f"I2C error: {e}")
            self.bus = None

    def measure(self):
        if not self.bus:
            return (None, None, True)

        try:
            self.bus.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
            start_time = time.monotonic()
            while True:
                status = self.bus.read_i2c_block_data(self.address, 0x71)
                if not status[0] & 0x80:
                    break
                if time.monotonic() - start_time > 0.1:
                    logger.error("Timeout waiting for measurement")
                    return (None, None, True)
                time.sleep(0.01)

            data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
            crc = self.crctab.crcit(data[1:6])
            crc_error = crc != data[6]

            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
            temperature_raw = (data[3] << 8) | data[4] | (data[5] >> 4)
            temperature_raw <<= 4
            temperature_raw |= (data[5] & 0x0F) << 4

            temperature = float(temperature_raw) / 5242.88 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0

            return (temperature, humidity, crc_error)

        except (IOError, OSError) as e:
            logger.error(f"I2C error: {e}")
            return (None, None, True)
        finally:
            self.bus.close()

if __name__ == "__main__":
    logging.basicConfig(level=logging.ERROR)

    try:
        dht20 = DHT20()
        if dht20.bus:
            result = dht20.measure()
            if not result[2]:
                print(f"Temperature: {result[0]:.2f}°C, Humidity: {result[1]:.2f}%")
            else:
                print("Error reading data")
        else:
            print("DHT20 not found")
    except KeyboardInterrupt:
        print("Exiting...")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")

