import RPi.I2C as I2C
import smbus2
import signal
import gpiozero
import board
import adafruit_mcp23017

class MCP23017:
    def __init__(self, i2c_bus=1, i2c_address=0x20):
        self.i2c = smbus2.SMBus(i2c_bus)
        self.address = i2c_address
        self.i2c.write_byte_data(self.address, 0x00, 0x00)  # IODIRA
        self.i2c.write_byte_data(self.address, 0x01, 0x01)  # IODIRB
        self.i2c.write_byte_data(self.address, 0x00, 0x12)  # GPIOA
        self.i2c.write_byte_data(self.address, 0x01, 0x13)  # GPIOB
        self.i2c.write_byte_data(self.address, 0x04, 0x80)  # GPPUB

    def read_input(self, pin):
        data = self.i2c.read_byte_data(self.address, pin)
        if data & (1 << (7 - pin)):
            return True
        return False

    def write_output(self, pin, value):
        if value:
            self.i2c.write_byte_data(self.address, 0x14, 1 << pin)
        else:
            self.i2c.write_byte_data(self.address, 0x14, ~(1 << pin))

def debounce(pin, delay=20):
    last_state = None
    current_state = pin.value
    debounced_state = current_state
    while True:
        time.sleep(0.01)
        current_state = pin.value
        if current_state != last_state:
            debounced_state = current_state
            last_state = current_state
        time.sleep(delay / 1000)
    return debounced_state

def main():
    mcp = MCP23017()
    led = gpiozero.LED(2)
    switch = gpiozero.InputDevice(board.GP18, pull_up=True)

    try:
        while True:
            switch_state = debounce(switch)
            if switch_state:
                mcp.write_output(0, True)
                print("Switch is HIGH")
            else:
                mcp.write_output(0, False)
                print("Switch is LOW")

    except KeyboardInterrupt:
        mcp.write_output(0, False)
        print("Exiting...")
        mcp.i2c.close()

if __name__ == "__main__":
    with I2C.I2C(1) as i2c:
        try:
            device = adafruit_mcp23017.MCP23017(i2c, address=0x20)
        except OSError as e:
            print(f"Error: {e}")
            exit(1)

        main()

