    try:
        bus.open()
        return True
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False

def sensor_present(address=0x23):
    try:
        bus.write_byte_data(address, Adafruit_BH1750.POWERON, Adafruit_BH1750.POWERON)
        response = bus.read_byte_data(address, Adafruit_BH1750.ID)
        if response == Adafruit_BH1750.ID:
            return True
    except Exception as e:
        print(f"Error checking for sensor at address 0x23: {e}")
        return False
    return False

def read_luminance():
    try:
        high_byte = bus.read_byte_data(Adafruit_BH1750.DEFAULT_ADDRESS, Adafruit_BH1750.HIGH_RES_MODE)
        low_byte = bus.read_byte_data(Adafruit_BH1750.DEFAULT_ADDRESS, Adafruit_BH1750.LOW_RES_MODE)
        luminance = (high_byte << 8 | low_byte) / 1.2
        return luminance
    except Exception as e:
        print(f"Error reading luminance: {e}")
        return None

def main():
    if not i2c_init():
        led.on()
        print("I2C bus initialization failed. Exiting...")
        exit(1)

    if not sensor_present():
        led.on()
        print("Light sensor not found at address 0x23. Exiting...")
        exit(1)

    bus.write_byte_data(Adafruit_BH1750.DEFAULT_ADDRESS, Adafruit_BH1750.CONTINOUS_HI_RES_MODE, Adafruit_BH1750.CONTINOUS_HI_RES_MODE)

    try:
        while True:
            luminance = read_luminance()
            if luminance is not None:
                print(f"Ambient luminance: {luminance:.2f} lux")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting...")
        led.off()
        bus.close()

