import paho.mqtt.client as mqtt

class RotaryEncoder:
    def __init__(self, clk_pin=17, dt_pin=18, debounce_time=0.005, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.debounce_time = debounce_time
        self.callback = callback
        self.counter = 0
        self.prev_clk_state = None
        self.dt_debouncer = Debouncer(dt_pin, hold_off=self.debounce_time)
        self.running = True
        self.event = Event()

        self.encoder_thread = Thread(target=self.encoder_loop)
        self.encoder_thread.daemon = True
        self.encoder_thread.start()

        if callable(self.callback):
            self.validate_callback(self.callback)

    def validate_callback(self, callback):
        if not callable(callback):
            raise ValueError("Callback must be a callable object.")

    def encoder_loop(self):
        clk_pin = gpiozero.Input(self.clk_pin, pull_up=True)
        dt_pin = self.dt_debouncer

        while self.running:
            try:
                clk_state = clk_pin.value
                dt_state = dt_pin.value

                if clk_state != self.prev_clk_state:
                    if dt_state:
                        self.counter += 1
                    else:
                        self.counter -= 1

                    if self.callback:
                        self.callback(self.counter)

                self.prev_clk_state = clk_state
                time.sleep(0.005)
            except Exception as e:
                print(f"Error in encoder loop: {e}")
                traceback.print_exc()

    def stop(self):
        self.running = False
        self.event.set()
        self.encoder_thread.join()

    def cleanup(self):
        self.stop()
        gpiozero.deinit()

class MqttPublisher:
    def __init__(self, topic, client_id):
        self.topic = topic
        self.client_id = client_id
        self.client = mqtt.Client(self.client_id)
        self.client.on_connect = self.on_connect
        self.client.on_publish = self.on_publish

    def on_connect(self, client, userdata, flags, rc):
        if rc == 0:
            print("Connected to MQTT broker")
            self.client.publish(self.topic, self.counter)
        else:
            print(f"Failed to connect, return code {rc}")

    def on_publish(self, client, userdata, mid):
        print(f"Published message with mid: {mid}")

    def publish(self, counter):
        self.counter = counter
        self.client.connect("mqtt.example.com", 1883, 60)
        self.client.publish(self.topic, self.counter)
        self.client.loop_start()

    def stop(self):
        self.client.loop_stop()

if __name__ == "__main__":
    encoder = RotaryEncoder(clk_pin=17, dt_pin=18)
    publisher = MqttPublisher(topic="rotaryencoder/counter", client_id="rotaryencoder")

    try:
        while True:
            pass
    except KeyboardInterrupt:
        encoder.stop()
        publisher.stop()
        encoder.cleanup()
        sys.exit(0)

