                    if dt_state:
                        self.counter += 1
                    else:
                        self.counter -= 1

                    if self.callback:
                        self.callback(self.counter)

                self.prev_clk_state = clk_state
                time.sleep(0.005)
            except Exception as e:
                print(f"Error in encoder loop: {e}")
                traceback.print_exc()

    def stop(self):
        self.running = False
        self.event.set()
        self.encoder_thread.join()

    def cleanup(self):
        self.stop()
        gpiozero.deinit()

class MqttPublisher:
    def __init__(self, topic, client_id):
        self.topic = topic
        self.client_id = client_id
        self.client = mqtt.Client(self.client_id)
        self.client.on_connect = self.on_connect
        self.client.on_publish = self.on_publish

    def on_connect(self, client, userdata, flags, rc):
        if rc == 0:
            print("Connected to MQTT broker")
            self.client.publish(self.topic, self.counter)
        else:
            print(f"Failed to connect, return code {rc}")

    def on_publish(self, client, userdata, mid):
        print(f"Published message with mid: {mid}")

    def publish(self, counter):
        self.counter = counter
        self.client.connect("mqtt.example.com", 1883, 60)
        self.client.publish(self.topic, self.counter)
        self.client.loop_start()

    def stop(self):
        self.client.loop_stop()

if __name__ == "__main__":
    encoder = RotaryEncoder(clk_pin=17, dt_pin=18)
    publisher = MqttPublisher(topic="rotaryencoder/counter", client_id="rotaryencoder")

    try:
        while True:
            pass
    except KeyboardInterrupt:
        encoder.stop()
        publisher.stop()
        encoder.cleanup()
        sys.exit(0)
```

This code defines a RotaryEncoder class that interfaces with a KY-040 rotary encoder using the gpiozero library. It also includes an MqttPublisher class that publishes the counter value to an MQTT broker. The main block handles KeyboardInterrupt gracefully and ensures resources are released on all exit paths.

