import os
import RPi.GPIO as GPIO
import time
import argparse
import logging
from gpiozero import Debouncer

def get_raspi_model():
    with open("/proc/cpuinfo", "r") as f:
        for line in f:
            if "Revision" in line:
                return line.split(":")[1].strip()
    return "Unknown"

def get_gpio_num():
    model = get_raspi_model()
    if model == "bcm2708" or model == "bcm2709":
        return 17
    else:
        return 26

def setup_gpio(gpio_ch, debounce=200):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    gpio_pins = [GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP) for pin in gpio_ch]
    debouncers = [Debouncer(pin, debounce=debounce) for pin in gpio_ch]
    return gpio_pins, debouncers

def main():
    parser = argparse.ArgumentParser(description="GPIO Monitor")
    parser.add_argument("-d", "--debounce", type=int, default=200, help="Debounce time in milliseconds (default: 200)")
    args = parser.parse_args()

    gpio_ch = [pin for pin in range(get_gpio_num()) if pin not in [14, 15]]  # Exclude pins used by the camera
    gpio_pins, debouncers = setup_gpio(gpio_ch, args.debounce)

    logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(message)s")
    logging.info(f"Detected Raspberry Pi model: {get_raspi_model()}")
    logging.info(f"Number of available GPIO pins: {get_gpio_num()}")
    logging.info("Monitoring...")

    state_log = {}

    try:
        while True:
            for i, (pin, debouncer) in enumerate(zip(gpio_ch, debouncers)):
                state = debouncer.wait_for_edge(Debouncer.FALLING, timeout=0.1)
                if state is not None:
                    if pin not in state_log:
                        state_log[pin] = not state
                    else:
                        state_log[pin] = not state_log[pin]

            logging.info(f"State changes: {state_log}")
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Shutting down...")
        GPIO.cleanup()
        exit(0)
    except RuntimeError as e:
        logging.error(f"Failed to import RPi.GPIO: {e}")
        exit(1)

if __name__ == "__main__":
    main()

