import time
import sys
import RPi.GPIO as GPIO
from gpiozero import LED
from pwm import PWM
from adafruit_blinka.driver.i2c import I2C
from adafruit_tsl2561 import TSL2561

# Set up GPIO for PWM on GPIO18
GPIO.setmode(GPIO.BCM)
GPIO.setup(18, GPIO.OUT)
pwm = PWM(18, 1000)

# I2C bus and TSL2561 sensor
i2c = I2C(1)
tsl = TSL2561(i2c, address=0x39)

def handle_i2c_error(func):
    def wrapper(*args, **kwargs):
        attempts = 3
        while attempts > 0:
            try:
                return func(*args, **kwargs)
            except OSError as e:
                if "Resource temporarily unavailable" in str(e):
                    print("I2C bus error, retrying...")
                    attempts -= 1
                    time.sleep(0.1)
                else:
                    raise
        raise Exception("Failed to communicate with TSL2561 after 3 attempts")
    return wrapper

@handle_i2c_error
def get_lux():
    return tsl.luminance

def map_lux_to_brightness(lux):
    return min(max(int(clamp(lux / 10, 0, 100)), 0), 100)

def clamp(value, min_value, max_value):
    return max(min_value, min(max_value, value))

def main():
    try:
        while True:
            lux = get_lux()
            brightness = map_lux_to_brightness(lux)
            pwm.duty_cycle = brightness
            print(f"Lux: {lux}, Brightness: {brightness}%")
            time.sleep(1)
    except KeyboardInterrupt:
        pwm.stop()
        GPIO.cleanup()
        sys.exit(0)

if __name__ == "__main__":
    main()

