import sys
import time
import logging
import gpiozero
import networkx as nx
import matplotlib.pyplot as plt
from picamera2 import Camera
from adafruit_motor import servo
from paho.mqtt import client as mqtt_client

# Grid dimensions
GRID_SIZE = (5, 5)
START_NODE = (0, 0)
END_NODE = (4, 4)

# MQTT broker settings
MQTT_BROKER = "your_mqtt_broker"
MQTT_PORT = 1883
MQTT_TOPIC = "robot/path"

# GPIO settings
LED = gpiozero.LED(18)
LED_ON_TIME = 2
LED_BLINK_PERIOD = 0.5
LED_BLINK_DURATION = LED_BLINK_PERIOD * 3

def setup_camera():
    camera = Camera()
    camera.start()
    return camera

def teardown_camera(camera):
    camera.stop()

def setup_servo():
    servo_pin = 17
    servo_min_angle = 0
    servo_max_angle = 180
    servo_mid_angle = (servo_min_angle + servo_max_angle) / 2
    return servo.Servo(servo_pin, min_pulse_width=servo_min_angle, max_pulse_width=servo_max_angle, angle=servo_mid_angle)

def teardown_servo(servo):
    servo.deinit()

def create_grid(grid_size):
    grid = nx.Graph()
    grid.add_nodes_from([(i, j) for i in range(grid_size[0]) for j in range(grid_size[1])])
    return grid

def is_valid_grid(grid):
    return len(grid) == len(set(grid)) and all(isinstance(node, tuple) and len(node) == 2 for node in grid)

def is_valid_grid_dimensions(grid_size):
    return len(grid_size) == 2 and all(isinstance(dim, int) for dim in grid_size)

def is_valid_start_end_nodes(start_node, end_node, grid):
    return all(0 <= node[0] < len(grid) and 0 <= node[1] < len(grid[0]) for node in [start_node, end_node])

def bfs(graph, start_node, end_node):
    visited = set()
    queue = [start_node]
    parents = {start_node: None}

    while queue:
        current_node = queue.pop(0)
        if current_node == end_node:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = parents[current_node]
            return path[::-1]

        visited.add(current_node)
        for neighbor in graph.neighbors(current_node):
            if neighbor not in visited:
                queue.append(neighbor)
                parents[neighbor] = current_node

    return None

def main():
    if not is_valid_grid_dimensions(GRID_SIZE):
        logging.error("Invalid grid dimensions")
        sys.exit(1)

    grid = create_grid(GRID_SIZE)

    for i, row in enumerate(grid):
        for j, _ in enumerate(row):
            if (i, j) == START_NODE or (i, j) == END_NODE:
                grid[i][j] = 0
            else:
                grid[i][j] = 1

    if not is_valid_start_end_nodes(START_NODE, END_NODE, grid):
        logging.error("Invalid start or end nodes")
        sys.exit(1)

    try:
        path = bfs(grid, START_NODE, END_NODE)

        if path:
            logging.info(f"Path length: {len(path)}")
            LED.on()
            time.sleep(LED_ON_TIME)
            LED.off()

            camera = setup_camera()
            servo = setup_servo()

            for i, (x, y) in enumerate(path):
                servo.angle = (i / len(path)) * 180
                time.sleep(0.1)
                camera.capture_sequence([(f"robot_path_{i}.jpg", "yuv420"),], format="jpeg", use_video_port=True)

            teardown_servo(servo)
            teardown_camera(camera)
        else:
            logging.error("No path found")
            LED.blink(LED_BLINK_PERIOD, LED_BLINK_DURATION)

    except KeyboardInterrupt:
        logging.info("Interrupted")

    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        LED.blink(LED_BLINK_PERIOD, LED_BLINK_DURATION)

    finally:
        if LED.is_lit:
            LED.off()

    if MQTT_BROKER:
        mqtt_client.Client().connect(MQTT_BROKER, MQTT_PORT, 60)
        mqtt_client.Client().publish(MQTT_TOPIC, f"{len(path) if path else 'No path found'}" if path else "No path found")
        mqtt_client.Client().disconnect()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    main()

