from adafruit_mqtt.client import MQTT_Client

class LEDController:
    def __init__(self, pin):
        try:
            self.led = gpiozero.LED(pin)
        except ValueError as e:
            print(f"Error initializing LED on pin {pin}: {e}")
            exit(1)

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration <= 0 or off_duration <= 0:
            print("Error: Durations must be positive.")
            return

        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

def mqtt_onoff_handler(client, userdata, message):
    command, pin_str = message.payload.decode().split(":")
    try:
        pin = int(pin_str)
    except ValueError:
        print("Error: Invalid pin number.")
        return

    if command == "on":
        led_controller.on(pin)
    elif command == "off":
        led_controller.off(pin)

def main():
    global led_controller
    led_controller = LEDController(25)

    mqtt_client = MQTT_Client("led_controller", "localhost")
    mqtt_client.on_message = mqtt_onoff_handler
    mqtt_client.connect()

    try:
        while True:
            led_controller.blink(1.0, 0.5)
            time.sleep(1.0)
    except KeyboardInterrupt:
        led_controller.off()
        mqtt_client.disconnect()
        print("Exiting...")

    finally:
        gpiozero.deinit()
        print("Goodbye!")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, lambda sig, frame: signal.SIG_DFL)
    signal.signal(signal.SIGTERM, lambda sig, frame: signal.SIG_DFL)
    main()

