    motor.angle = 90
    time.sleep(1)
    motor.angle = 0

def on_intrusion(client, userdata, msg):
    sensor_num, pin = msg.topic.split("_")
    sensor_num, pin = int(sensor_num), int(pin)
    logging.info(f"Intrusion Detected on sensor {sensor_num} ({pin})")

    if sensor_num in (1, 2):
        actuator = choice(ACTUATORS)
        activate_actuator(actuator)
    elif sensor_num == 3:
        for actuator in ACTUATORS:
            activate_actuator(actuator)

