            if read_sensor(17) or read_sensor(18):
                time.sleep(0.1)
                mqtt_client.publish(f"Sensor_1_{GPIO.input(17)}", "")
                mqtt_client.publish(f"Sensor_2_{GPIO.input(18)}", "")

                if read_sensor(17) and read_sensor(18):
                    time.sleep(0.1)
                    mqtt_client.publish("Confirmed_Intrusion", "")
                    for actuator in ACTUATORS:
                        activate_actuator(actuator)

    except RuntimeError as e:
        logging.error(f"Failed to initialize GPIO: {e}")
    except KeyboardInterrupt:
        logging.info("Exiting gracefully")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    setup_logging()
    main()

