import sys
import time
import busio
import adafruit_tcs34725
import Pillow
from PIL import Image, ImageEnhance, ImageColor
import signal
import paho.mqtt.client as mqtt

I2C_SCL = 3
I2C_SDA = 2
TCS34725_ADDR = 0x29
INTEGRATION_TIME_50MS = 50
GAIN_4X = 4

i2c = busio.I2C(SCL=I2C_SCL, SDA=I2C_SDA)

def init_i2c():
    try:
        i2c.initialize()
        return True
    except OSError as e:
        print(f"Error initializing I2C bus: {e}")
        return False

def init_tcs34725():
    if not init_i2c():
        return None

    sensor = adafruit_tcs34725.TCS34725(i2c, addr=TCS34725_ADDR)
    if not sensor.is_detected:
        print("TCS34725 sensor not detected")
        return None

    sensor.gain = GAIN_4X
    sensor.integration_time = INTEGRATION_TIME_50MS
    return sensor

def get_sensor_color_data(sensor):
    try:
        color_data = sensor.color_rgb_bytes
        return (color_data[0], color_data[1], color_data[2], color_data[3])
    except OSError as e:
        print(f"Error reading color data from TCS34725: {e}")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    try:
        image = Image.open(image_path)
    except (FileNotFoundError, Pillow.Image.ImageError) as e:
        print(f"Error opening image file: {e}")
        return (0, 0, 0)

    if image.mode != "RGB":
        print("Image mode is not RGB")
        return (0, 0, 0)

    image = image.resize((100, 100))
    pixels = image.getdata()
    colors = dict(Counter(pixels))
    dominant_color = max(colors, key=colors.get)
    return ImageColor.getrgb(dominant_color)

def main():
    sensor = init_tcs34725()
    if not sensor:
        print("TCS34725 sensor initialization failed")
        sys.exit(1)

    mqtt_client = mqtt.Client()
    mqtt_client.connect("localhost", 1883, 60)

    try:
        while True:
            sensor_color = get_sensor_color_data(sensor)
            dominant_image_color = find_dominant_image_color("image.jpg")

            print(f"Sensor color: R={sensor_color[0]}, G={sensor_color[1]}, B={sensor_color[2]}, Clear={sensor_color[3]}")
            print(f"Dominant image color: R={dominant_image_color[0]}, G={dominant_image_color[1]}, B={dominant_image_color[2]}")

            mqtt_message = f"Sensor: R={sensor_color[0]}, G={sensor_color[1]}, B={sensor_color[2]}, Clear={sensor_color[3]}\n" \
                           f"Image: R={dominant_image_color[0]}, G={dominant_image_color[1]}, B={dominant_image_color[2]}"
            mqtt_client.publish("color_data", mqtt_message)

            time.sleep(1)
    except KeyboardInterrupt:
        print("Shutting down...")
    except Exception as e:
        print(f"Error in main loop: {e}")

    sensor.deinit()
    i2c.deallocate()
    mqtt_client.disconnect()
    sys.exit(0)

if __name__ == "__main__":
    main()

