import time
import gpiozero
import signal
import picamera2

class SharedLEDBoard:
    def __init__(self, pins):
        self.pins = pins
        self.leds = [gpiozero.LED(pin) for pin in pins]

    def on(self):
        for led in self.leds:
            led.on()
        print("LEDs ON")

    def off(self):
        for led in self.leds:
            led.off()
        print("LEDs OFF")

    def __del__(self):
        self.off()

def led_cycle(led_board):
    for _ in range(5):
        led_board.on()
        time.sleep(1)
        led_board.off()
        time.sleep(1)

def signal_handler(signal, frame):
    print("Interrupted. Turning off LEDs...")
    led_board.off()
    led_board.leds[0].cleanup()
    led_board.leds[1].cleanup()

if __name__ == "__main__":
    try:
        led_board = SharedLEDBoard([18, 23])
        led_cycle(led_board)
    except KeyboardInterrupt:
        signal.signal(signal.SIGINT, signal_handler)
        led_board.off()
        led_board.leds[0].cleanup()
        led_board.leds[1].cleanup()

