import argparse
import logging
import os
import random
import time
import RPi.GPIO as GPIO
import signal
import adafruit_pwm
import adafruit_pwm.servo
import adafruit_bus_device.i2c_bus as I2C
import picamera2

class Buzzer:
    def __init__(self, gpio_pin, i2c_bus=None, i2c_address=None):
        self.gpio_pin = gpio_pin
        self.pwm = None
        self.servo = None

        if i2c_bus is None and i2c_address is None:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(gpio_pin, GPIO.OUT)
        else:
            i2c_bus = I2C.get_i2c_bus(1)
            self.servo = adafruit_pwm.servo.Servo(i2c_bus, i2c_address)

    def on(self):
        if self.pwm:
            self.pwm.start(50)
        elif self.servo:
            self.servo.angle = 0

    def off(self):
        if self.pwm:
            self.pwm.stop()
        elif self.servo:
            self.servo.angle = 90

    def chirp(self):
        frequency = random.uniform(20000, 25000)
        duty_cycle = 50
        pulse_length = 1 / frequency * duty_cycle / 100
        period_length = 1 / frequency
        pulse_count = int(period_length / pulse_length)

        if self.pwm:
            self.pwm.start(duty_cycle)
            self.pwm.change_duty_cycle(duty_cycle)
            time.sleep(pulse_length)
            self.pwm.stop()
        elif self.servo:
            self.servo.angle = 0
            time.sleep(pulse_length)
            self.servo.angle = 90

def setup_buzzers(gpio_buzzer1, gpio_buzzer2, gpio_led1=None, gpio_led2=None):
    buzzers = {
        'buzzer1': Buzzer(gpio_buzzer1),
        'buzzer2': Buzzer(gpio_buzzer2, gpio_buzzer1.i2c_bus, gpio_buzzer1.i2c_address)
    }

    if gpio_led1:
        buzzers['led1'] = GPIO.output(gpio_led1, False)
    if gpio_led2:
        buzzers['led2'] = GPIO.output(gpio_led2, False)

    return buzzers

def main(gpio_buzzer1, gpio_buzzer2, gpio_led1=None, gpio_led2=None, log_file='bird_deterrent.log'):
    buzzers = setup_buzzers(gpio_buzzer1, gpio_buzzer2, gpio_led1, gpio_led2)
    sensor_value = random.randint(0, 100)
    logger = logging.getLogger(__name__)
    logger.setLevel(logging.INFO)
    file_handler = logging.FileHandler(log_file)
    file_handler.setLevel(logging.INFO)
    formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
    file_handler.setFormatter(formatter)
    logger.addHandler(file_handler)

    try:
        while True:
            if sensor_value > 70:
                logger.info(f"Sensor value: {sensor_value}")
                for buzzer in buzzers.values():
                    buzzer.on()
                    buzzer.chirp()
                    if buzzer != buzzers['buzzer1']:
                        time.sleep(0.2)
                    else:
                        time.sleep(0.1)
                    buzzer.off()
                    if gpio_led1 and buzzer == buzzers['buzzer1']:
                        buzzers['led1'].toggle()
                    if gpio_led2 and buzzer == buzzers['buzzer2']:
                        buzzers['led2'].toggle()
                time.sleep(60)
                sensor_value = random.randint(0, 100)
            time.sleep(1)
    except KeyboardInterrupt:
        logger.info("Interrupted, cleaning up...")
    finally:
        for buzzer in buzzers.values():
            if buzzer.pwm:
                buzzer.pwm.stop()
            if buzzer.servo:
                buzzer.servo.angle = 90
        GPIO.cleanup()

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Bird deterrent script")
    parser.add_argument("--gpio_buzzer1", type=int, help="BCM pin for buzzer1 (required)", required=True)
    parser.add_argument("--gpio_buzzer2", type=int, help="BCM pin for buzzer2 (required)", required=True)
    parser.add_argument("--gpio_led1", type=int, help="BCM pin for LED1 (optional)")
    parser.add_argument("--gpio_led2", type=int, help="BCM pin for LED2 (optional)")
    parser.add_argument("--log_file", type=str, help="Log file (default 'bird_deterrent.log')")

    args = parser.parse_args()

    if not all(isinstance(arg, int) for arg in [args.gpio_buzzer1, args.gpio_buzzer2]):
        raise ValueError("gpio_buzzer1 and gpio_buzzer2 must be integers.")

    main(args.gpio_buzzer1, args.gpio_buzzer2, args.gpio_led1, args.gpio_led2, args.log_file)

import time
import atexit
import RPi.GPIO as GPIO
import sys
import Adafruit_I2C
import Adafruit_MotorHAT
import adafruit_motor
import paho.mqtt.client as mqtt

class DCMotorHATExtra(Adafruit_MotorHAT):
    def __init__(self, i2c_bus=1, address=0x60):
        super().__init__(i2c_bus, address)
        self.pwm_freq = 60
        self.motors = [None] * 4
        self.i2c = Adafruit_I2C.get_i2c_bus(self.i2c_bus)
        try:
            self.i2c.write_byte_data(self.address, Adafruit_MotorHAT.PWM_FREQ_REG, self.pwm_freq)
        except (OSError, Adafruit_I2C.I2CError) as e:
            print(f"Error initializing I2C: {e}")
            sys.exit(1)

    def set_pwm_freq(self, freq):
        self.pwm_freq = freq
        self.i2c.write_byte_data(self.address, Adafruit_MotorHAT.PWM_FREQ_REG, self.pwm_freq)

    def get_pwm_freq(self):
        return self.pwm_freq

    def __del__(self):
        for motor in self.motors:
            if motor:
                motor.release()

    def signal_handler(signal, frame):
        print("Received SIGINT or SIGTERM, cleaning up...")
        for motor in self.motors:
            if motor:
                motor.stop()
        sys.exit(0)

class DCMotor:
    def __init__(self, hat, motor_num, pwm_freq=None, invert=False):
        if not (1 <= motor_num <= 4):
            raise ValueError("Invalid motor number")
        self.hat = hat
        self.motor_num = motor_num
        self.pwm_freq = pwm_freq or self.hat.get_pwm_freq()
        self.invert = invert
        self.last_duty_cycle = 0
        self.motor = DCMotorHATExtra.RELEASE if not self.hat.motors[motor_num - 1] else self.hat.motors[motor_num - 1]
        self.hat.motors[motor_num - 1] = self
        self.hat.i2c.write_byte_data(self.hat.address, Adafruit_MotorHAT.MOTOR_PWM_REG(motor_num - 1), self.last_duty_cycle)
        GPIO.add_signal_handler(signal.SIGINT, DCMotorHATExtra.signal_handler)
        GPIO.add_signal_handler(signal.SIGTERM, DCMotorHATExtra.signal_handler)

    def set_dc(self, duty_cycle):
        if duty_cycle < -255 or duty_cycle > 255:
            raise ValueError("Duty cycle out of range")
        self.last_duty_cycle = max(-255, min(255, duty_cycle))
        direction = (self.last_duty_cycle > 0) ^ self.invert
        if self.last_duty_cycle == 0:
            self.motor = DCMotorHATExtra.RELEASE
        else:
            self.motor = direction * Adafruit_MotorHAT.FORWARD + (not direction) * Adafruit_MotorHAT.BACKWARD
