class DCMotorHATExtra(Adafruit_MotorHAT):
    def __init__(self, i2c_bus=1, address=0x60):
        super().__init__(i2c_bus, address)
        self.pwm_freq = 60
        self.motors = [None] * 4
        self.i2c = Adafruit_I2C.get_i2c_bus(self.i2c_bus)
        try:
            self.i2c.write_byte_data(self.address, Adafruit_MotorHAT.PWM_FREQ_REG, self.pwm_freq)
        except (OSError, Adafruit_I2C.I2CError) as e:
            print(f"Error initializing I2C: {e}")
            sys.exit(1)

    def set_pwm_freq(self, freq):
        self.pwm_freq = freq
        self.i2c.write_byte_data(self.address, Adafruit_MotorHAT.PWM_FREQ_REG, self.pwm_freq)

    def get_pwm_freq(self):
        return self.pwm_freq

    def __del__(self):
        for motor in self.motors:
            if motor:
                motor.release()

    def signal_handler(signal, frame):
        print("Received SIGINT or SIGTERM, cleaning up...")
        for motor in self.motors:
            if motor:
                motor.stop()
        sys.exit(0)

class DCMotor:
    def __init__(self, hat, motor_num, pwm_freq=None, invert=False):
        if not (1 <= motor_num <= 4):
            raise ValueError("Invalid motor number")
        self.hat = hat
        self.motor_num = motor_num
        self.pwm_freq = pwm_freq or self.hat.get_pwm_freq()
        self.invert = invert
        self.last_duty_cycle = 0
        self.motor = DCMotorHATExtra.RELEASE if not self.hat.motors[motor_num - 1] else self.hat.motors[motor_num - 1]
        self.hat.motors[motor_num - 1] = self
        self.hat.i2c.write_byte_data(self.hat.address, Adafruit_MotorHAT.MOTOR_PWM_REG(motor_num - 1), self.last_duty_cycle)
        GPIO.add_signal_handler(signal.SIGINT, DCMotorHATExtra.signal_handler)
        GPIO.add_signal_handler(signal.SIGTERM, DCMotorHATExtra.signal_handler)

    def set_dc(self, duty_cycle):
        if duty_cycle < -255 or duty_cycle > 255:
            raise ValueError("Duty cycle out of range")
        self.last_duty_cycle = max(-255, min(255, duty_cycle))
        direction = (self.last_duty_cycle > 0) ^ self.invert
        if self.last_duty_cycle == 0:
            self.motor = DCMotorHATExtra.RELEASE
        else:
            self.motor = direction * Adafruit_MotorHAT.FORWARD + (not direction) * Adafruit_MotorHAT.BACKWARD
        self.hat.i2c.write_byte_data(self.hat.address, Adafruit_MotorHAT.MOTOR_PWM_REG(self.motor_num - 1), self.last_duty_cycle)

    def stop(self):
        self.set_dc(0)

