import sys
import time
import pigpio
import MotorError

class Motor:
    def __init__(self, pi, motor_pin=18):
        if not isinstance(pi, pigpio.pi):
            raise MotorError("Invalid or disconnected pigpio instance")

        self.pi = pi
        self.motor_pin = motor_pin
        self.pi.set_mode(self.motor_pin, pigpio.OUTPUT)
        self.pi.set_PWM_frequency(self.motor_pin, 1000)
        self.duty_cycle = 0

    def set_frequency(self, freq):
        if not isinstance(freq, int) or freq <= 0:
            raise MotorError("Invalid frequency")

        if not self.pi.set_PWM_frequency(self.motor_pin, freq):
            raise MotorError("Failed to set PWM frequency")

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or duty < 0 or duty > 255:
            raise MotorError("Invalid duty cycle")

        if not self.pi.set_PWM_dutycycle(self.motor_pin, duty):
            raise MotorError("Failed to set duty cycle")

        self.duty_cycle = duty

    def stop(self):
        if not self.pi.set_PWM_dutycycle(self.motor_pin, 0):
            raise MotorError("Failed to stop motor")

    def __del__(self):
        self.stop()
        self.pi.stop()

    def close(self):
        self.stop()
        self.pi.stop()
        self.pi.terminate()

class MotorError(Exception):
    pass

if __name__ == "__main__":
    try:
        import pigpio
        pi = pigpio.pi()
        motor = Motor(pi, motor_pin=18)
        motor.set_frequency(2000)
        motor.set_duty_cycle(128)
        time.sleep(5)
        motor.stop()
        motor.close()
        pi.terminate()
    except MotorError as e:
        print(f"Error: {e}")
    except KeyboardInterrupt:
        motor.stop()
        motor.close()
        pi.terminate()

