import time
import gpiozero
import RPi.GPIO as GPIO
import adafruit_motor
import adafruit_servokit
import paho.mqtt.client as mqtt
from adafruit_motor import servo

class RoboticArm:
    def __init__(self):
        self.servos = {
            'base': None,
            'shoulder': None,
            'gripper': None
        }

        self.kit = adafruit_servokit.ServoKit(channel_range=1, bus=GPIO.I2C)

        try:
            for joint in ('base', 'shoulder', 'gripper'):
                servo_pin = {
                    'base': GPIO.BCM.GPIO17,
                    'shoulder': GPIO.BCM.GPIO27,
                    'gripper': GPIO.BCM.GPIO22
                }[joint]

                if gpiozero.Source(servo_pin).is_used:
                    raise ValueError(f"Pin {servo_pin} is already in use.")

                self.servos[joint] = servo.Servo(self.kit.get_servo_by_channel(joint))
                self.servos[joint].min_pulse_width = 0.005
                self.servos[joint].max_pulse_width = 0.025
                self.servos[joint].frequency = 50

        except (gpiozero.exc.OutputDeviceBadValue, ValueError, RuntimeError) as e:
            print(f"Error initializing servos: {e}")
            for servo in self.servos.values():
                if servo is not None:
                    servo.deinit()
            raise

    def move_joint(self, servo, target_angle):
        if target_angle < -90 or target_angle > 90:
            raise gpiozero.exc.OutputDeviceBadValue(f"Invalid angle: {target_angle}")

        servo.angle = target_angle
        time.sleep(0.4)
        servo.angle = None

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        self.move_joint(self.servos['base'], base_angle)
        self.move_joint(self.servos['shoulder'], shoulder_angle)
        self.move_joint(self.servos['gripper'], gripper_angle)

    def release(self):
        for servo in self.servos.values():
            if servo is not None:
                servo.deinit()

    def run_demo_sequence(self):
        poses = [(0, 0, 0), (45, -30, 20), (-45, 30, -20), (0, 0, 0)]

        for pose in poses:
            print(f"Moving to pose: {pose}")
            self.go_to_pose(*pose)
            time.sleep(2)

        self.go_to_pose(*poses[-1])

def on_connect(client, userdata, flags, rc):
    print("Connected to MQTT broker")
    client.subscribe("#")

def on_message(client, userdata, msg):
    try:
        pose = eval(msg.payload.decode())
        arm.go_to_pose(*pose)
    except Exception as e:
        print(f"Error processing MQTT message: {e}")

def main():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    arm = RoboticArm()
    try:
        mqtt_client = mqtt.Client()
        mqtt_client.on_connect = on_connect
        mqtt_client.on_message = on_message
        mqtt_client.connect("mqtt.example.com", 1883, 60)
        mqtt_client.loop_forever()

        arm.run_demo_sequence(arm)
    except KeyboardInterrupt:
        print("Interrupted, cleaning up...")
    except Exception as e:
        print(f"Error in main loop: {e}")
    finally:
        arm.release()
        GPIO.cleanup()
        mqtt_client.disconnect()

if __name__ == "__main__":
    main()

