import time
import serial
import struct
import pymodbus
from pymodbus.client.sync import ModbusSerialClient as ModbusClient
from pymodbus.exceptions import SerialException, ModbusException
import gpiozero
import signal
import logging
from adafruit_motor import servo

class Servo:
    def __init__(self, servo_pin, baudrate=115200):
        self.servo = servo.Servo(servo_pin)
        self.serial = serial.Serial("/dev/serial0", baudrate, timeout=1)
        self.client = ModbusClient(self.serial, timeout=1)
        self.register_map = {
            "STATUS": {"R/W": "R", "Register": 0x3000, "functioncode": 3},
            "CONTROL": {"R/W": "W", "Register": 0x3100, "functioncode": 6, "Value": {"Stop": 0x0006, "Start": 0x000F}},
            "OPMODE": {"R/W": "W", "Register": 0x3500, "functioncode": 6, "Value": {"Position": 1}},
            "VelocityFeedback": {"R/W": "R", "Register": 0x3B00, "functioncode": 3, "read_length": 2},
            "PositionFeedback": {"R/W": "R", "Register": 0x3700, "functioncode": 3, "read_length": 2},
            "VelocityCommand": {"R/W": "W", "Register": 0x6F00, "functioncode": 6},
            "PositionCommand": {"R/W": "W", "Register": 0x4000, "functioncode": 6},
        }
        self.servo_angle = 0
        self.velocity = 0
        self.position = 0
        self.status = None
        self.opmode = None
        self.velocity_feedback = None
        self.position_feedback = None
        self.log = logging.getLogger(__name__)

    def __del__(self):
        self.close()

    def close(self):
        self.servo.deinit()
        self.client.close()
        self.serial.close()

    def read_registers(self, reg_addr, reg_count, func_code):
        try:
            data = self.client.read_holding_registers(reg_addr, reg_count, unit=1, function_code=func_code)
            return data.registers
        except (SerialException, ModbusException) as e:
            self.log.warning(f"Error reading registers: {e}")
            return None

    def write_register(self, reg_addr, value, func_code):
        try:
            self.client.write_register(reg_addr, value, unit=1, function_code=func_code)
            return True
        except (SerialException, ModbusException) as e:
            self.log.warning(f"Error writing register: {e}")
            return False

    def set_servo_angle(self, angle):
        if 0 <= angle <= 180:
            self.servo_angle = angle
            self.write_register(self.PositionCommand, angle, self.register_map["PositionCommand"]["functioncode"])
            self.servo.angle = self.servo_angle
        else:
            self.log.warning(f"Invalid servo angle: {angle}")

    def set_velocity(self, velocity):
        if velocity >= 0:
            self.velocity = velocity
            self.write_register(self.VelocityCommand, velocity, self.register_map["VelocityCommand"]["functioncode"])
        else:
            self.log.warning(f"Invalid velocity: {velocity}")

    def read_status(self):
        data = self.read_registers(self.register_map["STATUS"]["Register"], 2, self.register_map["STATUS"]["functioncode"])
        if data:
            self.status = {
                "Error": data[0],
                "Moving": data[1]
            }
        else:
            self.status = None
        return self.status

    def read_opmode(self):
        data = self.read_registers(self.register_map["OPMODE"]["Register"], 1, self.register_map["OPMODE"]["functioncode"])
        if data:
            self.opmode = data[0]
        else:
            self.opmode = None
        return self.opmode

    def read_velocity_feedback(self):
        data = self.read_registers(self.register_map["VelocityFeedback"]["Register"], self.register_map["VelocityFeedback"]["read_length"], self.register_map["VelocityFeedback"]["functioncode"])
        if data:
            self.velocity_feedback = struct.unpack(">H", data)[0]
        else:
            self.velocity_feedback = None
        return self.velocity_feedback

    def read_position_feedback(self):
        data = self.read_registers(self.register_map["PositionFeedback"]["Register"], self.register_map["PositionFeedback"]["read_length"], self.register_map["PositionFeedback"]["functioncode"])
        if data:
            self.position_feedback = struct.unpack(">H", data)[0]
        else:
            self.position_feedback = None
        return self.position_feedback

    def start(self):
        if self.read_opmode() is None:
            self.write_register(self.register_map["OPMODE"]["Register"], self.register_map["OPMODE"]["Value"]["Position"], self.register_map["OPMODE"]["functioncode"])
        self.write_register(self.register_map["CONTROL"]["Register"], self.register_map["CONTROL"]["Value"]["Start"], self.register_map["CONTROL"]["functioncode"])

    def stop(self):
        self.write_register(self.register_map["CONTROL"]["Register"], self.register_map["CONTROL"]["Value"]["Stop"], self.register_map["CONTROL"]["functioncode"])

    def run(self):
        try:
            self.start()
            while True:
                self.read_status()
                self.read_opmode()
                self.read_velocity_feedback()
                self.read_position_feedback()
                time.sleep(1)
        except KeyboardInterrupt:
            self.stop()
            self.close()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, lambda sig, frame: Servo.stop(Servo))
    servo = Servo(17)
    servo.run()

