from paho.mqtt import client as mqtt_client
import uasyncio as asyncio
from gps import GPSD

class SimpleGPS:
    def __init__(self, gps_port="/dev/serial0", baudrate=9600, mqtt_broker="localhost", mqtt_port=1883):
        self.gps_port = gps_port
        self.baudrate = baudrate
        self.mqtt_broker = mqtt_broker
        self.mqtt_port = mqtt_port
        self.serial = None
        self.mqtt_client = mqtt_client.Client()

    async def _connect_serial(self):
        try:
            self.serial = adafruit_serial.AdafruitSerial(self.gps_port, self.baudrate)
            return True
        except (serial.SerialException, OSError) as e:
            logging.error(f"Failed to connect to serial port {self.gps_port}: {e}")
            return False

    def _read_data(self):
        try:
            if self.serial.any_in_waiting:
                data = self.serial.read(self.serial.in_waiting).decode("utf-8", errors="ignore").strip()
                if data.startswith("$GPGGA") or data.startswith("$GNGGA"):
                    return data
            return None
        except serial.SerialException as e:
            logging.error(f"Error reading from serial port: {e}")
        return None

    def _parse_gga(self, sentence):
        try:
            if sentence.startswith("$GPGGA"):
                gga = gps.message.GPGGA(sentence)
            elif sentence.startswith("$GNGGA"):
                gga = gps.message.GNPGGA(sentence)
            else:
                return None

            utc_time = time.strptime(gga.utc, "%Y%m%d%H%M%S.%f")
            latitude = gga.latitude * (180 / math.pi)
            longitude = gga.longitude * (180 / math.pi)
            fix_quality = gga.fix_quality
            num_satellites = gga.satellites

            return {
                "utc_time": time.strftime("%Y-%m-%d %H:%M:%S", utc_time),
                "latitude": latitude if latitude is not None else None,
                "longitude": longitude if longitude is not None else None,
                "fix_quality": fix_quality,
                "num_satellites": num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing NMEA sentence: {e}")
        return None

    def _close_serial(self):
        try:
            if self.serial:
                self.serial.close()
                self.serial = None
        except serial.SerialException as e:
            logging.error(f"Error closing serial port: {e}")

    def connect(self):
        if not self._connect_serial():
            return False
        self.gpsd = GPSD()
        self.gpsd.stream(self._on_nmea, force_sync=True)
        return True

    def _on_nmea(self, sentence):
        parsed_data = self._parse_gga(sentence)
        if parsed_data:
            self.mqtt_client.publish("gps/data", json.dumps(parsed_data))

    def close(self):
        self._close_serial()
        self.gpsd.stream(None)

    def read_data(self):
        data = self._read_data()
        if data:
            return data
        elif self.serial and not self.serial.is_open:
            logging.warning("Serial connection closed")
        return None

    def run_mqtt(self):
        self.mqtt_client.on_connect = self._on_connect
        self.mqtt_client.on_disconnect = self._on_disconnect
        self.mqtt_client.connect(self.mqtt_broker, self.mqtt_port)
        self.mqtt_client.loop_forever()

def _on_connect(client, userdata, flags, rc):
    if rc == 0:
        logging.info("Connected to MQTT broker")
    else:
        logging.error(f"Failed to connect to MQTT broker: {rc}")

def _on_disconnect(client, userdata, rc):
    if rc == 20:
        logging.info("Disconnected from MQTT broker")
    else:
        logging.error(f"Unexpected disconnection from MQTT broker: {rc}")

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)

    gps = SimpleGPS()
    if not gps.connect():
        sys.exit(1)

    try:
        gps.run_mqtt()
        while True:
            data = gps.read_data()
            if data:
                parsed_data = gps._parse_gga(data)
                if parsed_data:
                    logging.info(f"Received GPS data: {parsed_data}")
    except KeyboardInterrupt:
        gps.close()
        sys.exit(0)

