class SerialCommunicator:
    def __init__(self, port):
        self.port = port
        self.lock = threading.Lock()
        self.ser = None

    def __enter__(self):
        with self.lock:
            if not self.ser:
                try:
                    self.ser = serial.Serial(self.port, 9600, timeout=1)
                except SerialException as e:
                    raise e

        return self.ser

    def __exit__(self, exc_type, exc_val, exc_tb):
        with self.lock:
            if self.ser:
                self.ser.close()
                self.ser = None

    def send(self, cmd):
        with self.ser as ser:
            ser.write(cmd.encode())
            if len(ser.write(cmd.encode())) != len(cmd):
                raise SerialException("Invalid byte count")
            ser.flush()

    def receive_line(self):
        with self.ser as ser:
            try:
                return ser.read_until(b'\n').decode().strip()
            except serial.serialutil.SerialTimeoutException:
                return None

class DataManager:
