def find_bluetooth_device():
    session = ScanSession(duration=10)
    devices = session.scan(Providers.ADVERTISING_PACKET)

    for device in devices:
        if device.address == "XX:XX:XX:XX:XX:XX":  # Replace with the MAC address of your device
            return serial.Serial('/dev/rfcomm4', baudrate=38400, timeout=1)

    raise RuntimeError("Bluetooth device not found")

